/** Per-keypoint temporal filter bank: constant-velocity KF with innovation gating and NIS-adaptive measurement noise. */
import { ConstantVelocityKF, CHI2_1DOF_99 } from './kalman.js';
interface Track { kx: ConstantVelocityKF; ky: ConstantVelocityKF; t: number; nisEma: number; outliers: number; missed: number; n: number }
export interface FilterOptions { accel: number; r0: number; resetAfterMissed?: number; jumpAfterOutliers?: number }
