/**
 * Camera intrinsics priors and distortion handling (design section D1).
 * Nothing here claims calibration: priors are ASSUMED until a posterior (face self-cal or
 * Zhang checkerboard) tightens them below the gate.
 */
import type { Epistemic } from './epistemic.js';

export interface Intrinsics {
  fx: number; fy: number; cx: number; cy: number;
  k1: number; k2: number; p1: number; p2: number;
}
export interface IntrinsicsEstimate {
  K: Intrinsics;
  /** Relative sigma of focal length (sigma_f / f). */
  relSigmaF: number;
  source: 'PRIOR_FOV' | 'SELF_CAL_FACE' | 'FIDUCIAL_ZHANG';
  status: Epistemic;
}

export function focalFromHfov(widthPx: number, hfovDeg: number): number {
  return widthPx / 2 / Math.tan((hfovDeg * Math.PI) / 360);
}

/** Prior from an assumed horizontal FOV. Always ASSUMED. Typical webcam HFOV is uncertain: ~15% on f. */
export function priorIntrinsics(width: number, height: number, hfovDeg = 70, relSigmaF = 0.15): IntrinsicsEstimate {
  const f = focalFromHfov(width, hfovDeg);
  return { K: { fx: f, fy: f, cx: width / 2, cy: height / 2, k1: 0, k2: 0, p1: 0, p2: 0 }, relSigmaF, source: 'PRIOR_FOV', status: 'ASSUMED' };
}

/** Intrinsics can be called MEASURED only from a source that actually measures them, and tight enough. */
export function classifyIntrinsics(source: IntrinsicsEstimate['source'], relSigmaF: number, gate = 0.1): Epistemic {
  if (source === 'PRIOR_FOV') return 'ASSUMED';
  return relSigmaF <= gate ? 'MEASURED' : 'ASSUMED';
}

export function distortNormalized(x: number, y: number, K: Intrinsics): [number, number] {
  const r2 = x * x + y * y;
  const rad = 1 + K.k1 * r2 + K.k2 * r2 * r2;
  return [x * rad + 2 * K.p1 * x * y + K.p2 * (r2 + 2 * x * x), y * rad + K.p1 * (r2 + 2 * y * y) + 2 * K.p2 * x * y];
}

/** Undistort a pixel to normalized camera coordinates (fixed-point iteration). */
export function undistortPixel(u: number, v: number, K: Intrinsics, iters = 20): [number, number] {
  const xd = (u - K.cx) / K.fx, yd = (v - K.cy) / K.fy;
  let x = xd, y = yd;
  for (let i = 0; i < iters; i++) {
    const r2 = x * x + y * y;
    const rad = 1 + K.k1 * r2 + K.k2 * r2 * r2;
    const dx = 2 * K.p1 * x * y + K.p2 * (r2 + 2 * x * x);
    const dy = K.p1 * (r2 + 2 * y * y) + 2 * K.p2 * x * y;
    x = (xd - dx) / rad; y = (yd - dy) / rad;
  }
  return [x, y];
}

export function projectPoint(P: [number, number, number], K: Intrinsics): [number, number] {
  if (P[2] <= 0) throw new RangeError('point behind camera');
  const [xd, yd] = distortNormalized(P[0] / P[2], P[1] / P[2], K);
  return [K.fx * xd + K.cx, K.fy * yd + K.cy];
}
