/**
 * Continuous self-audit (spec item 16). A failed essential check refuses only the
 * quantities that depend on it, not the whole session.
 */
export interface AuditCheck { id: string; ok: boolean; detail?: string; essentialFor: string[] }
export interface AuditResult {
  allOk: boolean;
  failed: AuditCheck[];
  /** quantity id -> ids of failed checks that block it */
  refusals: Record<string, string[]>;
}
export function runAudit(checks: AuditCheck[]): AuditResult {
  const failed = checks.filter((c) => !c.ok);
  const refusals: Record<string, string[]> = {};
  for (const c of failed) for (const q of c.essentialFor) (refusals[q] ??= []).push(c.id);
  return { allOk: failed.length === 0, failed, refusals };
}
export function isRefused(a: AuditResult, quantityId: string): boolean {
  return (a.refusals[quantityId]?.length ?? 0) > 0;
}
