/**
 * Scalar constant-velocity Kalman filter (design section D4).
 *
 * Differences from the legacy fixed-noise EKF noted in the handoff:
 *  - process noise scales with the real frame interval dt;
 *  - measurement noise r is supplied per update (from heatmap covariance / edge residuals);
 *  - outliers are rejected by a chi-square innovation gate, and reported;
 *  - normalized innovation squared (NIS) is tracked so the filter can be checked for honesty.
 */

/** 99% chi-square threshold for 1 degree of freedom. */
export const CHI2_1DOF_99 = 6.635;

export interface UpdateResult {
  accepted: boolean;
  /** Normalized innovation squared y^2 / S. Expected mean 1 for a consistent filter. */
  nis: number;
  innovation: number;
}

export class ConstantVelocityKF {
  x = 0;
  v = 0;
  // covariance [[p00, p01], [p01, p11]]
  p00: number;
  p01 = 0;
  p11: number;
  initialised = false;
  readonly nisHistory: number[] = [];
  rejected = 0;

  constructor(
    /** Acceleration spectral density q (units^2 / s^3). */
    private readonly q: number,
    initialPosVar = 1e6,
    initialVelVar = 1e6,
  ) {
    this.p00 = initialPosVar;
    this.p11 = initialVelVar;
  }

  predict(dt: number): void {
    if (!(dt > 0)) throw new RangeError('dt must be positive');
    this.x += this.v * dt;
    const { p00, p01, p11, q } = this;
    this.p00 = p00 + 2 * dt * p01 + dt * dt * p11 + (q * dt ** 3) / 3;
    this.p01 = p01 + dt * p11 + (q * dt ** 2) / 2;
    this.p11 = p11 + q * dt;
  }

  update(z: number, r: number, gate = CHI2_1DOF_99): UpdateResult {
    if (!(r > 0)) throw new RangeError('measurement variance r must be positive');
    if (!this.initialised) {
      this.x = z;
      this.p00 = r;
      this.initialised = true;
      return { accepted: true, nis: 0, innovation: 0 };
    }
    const y = z - this.x;
    const s = this.p00 + r;
    const nis = (y * y) / s;
    if (nis > gate) {
      this.rejected += 1;
      return { accepted: false, nis, innovation: y };
    }
    const k0 = this.p00 / s;
    const k1 = this.p01 / s;
    this.x += k0 * y;
    this.v += k1 * y;
    const { p00, p01, p11 } = this;
    this.p00 = p00 - k0 * p00;
    this.p01 = p01 - k0 * p01;
    this.p11 = p11 - k1 * p01;
    this.nisHistory.push(nis);
    return { accepted: true, nis, innovation: y };
  }

  get positionSigma(): number {
    return Math.sqrt(this.p00);
  }
}

export interface NisReport {
  n: number;
  meanNis: number;
  /** Approximate two-sided 95% band for the mean of n chi2(1) variables. */
  low: number;
  high: number;
  verdict: 'CONSISTENT' | 'OVERCONFIDENT' | 'UNDERCONFIDENT' | 'INSUFFICIENT_DATA';
}

/**
 * Filter honesty check. Mean NIS well above 1 means r or q are too small (overconfident);
 * well below 1 means they are too large.
 */
export function nisConsistency(history: readonly number[], minSamples = 30): NisReport {
  const n = history.length;
  if (n < minSamples) {
    return { n, meanNis: Number.NaN, low: Number.NaN, high: Number.NaN, verdict: 'INSUFFICIENT_DATA' };
  }
  let s = 0;
  for (const h of history) s += h;
  const m = s / n;
  const half = 1.96 * Math.sqrt(2 / n);
  const low = 1 - half;
  const high = 1 + half;
  return {
    n,
    meanNis: m,
    low,
    high,
    verdict: m > high ? 'OVERCONFIDENT' : m < low ? 'UNDERCONFIDENT' : 'CONSISTENT',
  };
}
