import { useEffect, useMemo, useRef, useState } from 'react';
import type { RgbaImage, Point } from '@core/perception/pipeline';
import { lumaOf } from '@core/perception/pipeline';
import { estimateScale, fromIpdPrior, fromToothWidth, type ScaleEstimate, type ScaleHypothesis, DEFAULT_CENTRAL_INCISOR_MM, DEFAULT_CENTRAL_INCISOR_SIGMA_MM } from '@core/scale';
import { hypothesisFromCard, hypothesisFromMeasuredTooth, pickLength, withPlaneUncertainty } from '@core/scalePick';
import { Banner, Chip } from './common';

type Method = 'card' | 'tooth' | 'default';
export interface WizardProps { snapshot: RgbaImage; initial: ScaleHypothesis[]; ipdPx?: number | null; onApply(h: ScaleHypothesis[], estimate: ScaleEstimate): void; onClose(): void }

export function ScaleWizard({ snapshot, initial, ipdPx, onApply, onClose }: WizardProps) {
  const canvas = useRef<HTMLCanvasElement>(null);
  const gray = useMemo(() => lumaOf(snapshot), [snapshot]);
  const [method, setMethod] = useState<Method>('card'), [edge, setEdge] = useState<'long' | 'short'>('long'), [toothMm, setToothMm] = useState('8.5');
  const [taps, setTaps] = useState<Point[]>([]), [hyps, setHyps] = useState<ScaleHypothesis[]>(initial), [msg, setMsg] = useState<string | null>(null);
  const estimate = useMemo(() => (hyps.length ? estimateScale(hyps) : null), [hyps]);

  useEffect(() => {
    const c = canvas.current, ctx = c?.getContext('2d'); if (!c || !ctx) return;
    c.width = snapshot.width; c.height = snapshot.height; ctx.putImageData(snapshot as ImageData, 0, 0);
    ctx.strokeStyle = '#22d3ee'; ctx.fillStyle = '#22d3ee'; ctx.lineWidth = Math.max(1, snapshot.width / 600);
    taps.forEach((p) => { ctx.beginPath(); ctx.arc(p.x, p.y, Math.max(3, snapshot.width / 250), 0, 6.283); ctx.fill(); });
    if (taps.length === 2) { ctx.beginPath(); ctx.moveTo(taps[0]!.x, taps[0]!.y); ctx.lineTo(taps[1]!.x, taps[1]!.y); ctx.stroke(); }
  }, [snapshot, taps]);

  const onTap = (e: React.PointerEvent<HTMLCanvasElement>) => {
    const r = e.currentTarget.getBoundingClientRect();
    const p = { x: ((e.clientX - r.left) / r.width) * snapshot.width, y: ((e.clientY - r.top) / r.height) * snapshot.height };
    setMsg(null); setTaps((t) => (t.length >= 2 ? [p] : [...t, p]));
  };
  const add = () => {
    try {
      if (taps.length !== 2) throw new RangeError('Tap two points first.');
      let h: ScaleHypothesis;
      if (method === 'card') h = hypothesisFromCard(gray, taps[0]!, taps[1]!, edge);
      else if (method === 'tooth') h = hypothesisFromMeasuredTooth(gray, taps[0]!, taps[1]!, Number(toothMm));
      else { const r = pickLength(gray, taps[0]!, taps[1]!); h = withPlaneUncertainty(fromToothWidth({ widthMm: DEFAULT_CENTRAL_INCISOR_MM, sigmaMm: DEFAULT_CENTRAL_INCISOR_SIGMA_MM, widthPx: r.lengthPx, sigmaPx: r.sigmaPx, measuredByClinician: false }), 0.01); }
      setHyps((x) => [...x, h]); setTaps([]);
    } catch (e) { setMsg((e as Error).message); }
  };
  return (
    <section aria-label="Scale calibration">
      <h2>Set the scale</h2>
      <p>Without a real reference, results stay in ratios and angles. Tap both ends of a known length on the frozen frame; taps snap to the nearest edge.</p>
      <div className="row" role="radiogroup" aria-label="Scale method">
        <label><input type="radio" name="m" checked={method === 'card'} onChange={() => setMethod('card')} /> Bank/ID card (85.60 × 53.98 mm) held at the lips</label>
        <label><input type="radio" name="m" checked={method === 'tooth'} onChange={() => setMethod('tooth')} /> Tooth width I measured</label>
        <label><input type="radio" name="m" checked={method === 'default'} onChange={() => setMethod('default')} /> Population default 8.5 mm (assumed)</label>
      </div>
      {method === 'card' && <label>Edge tapped <select value={edge} onChange={(e) => setEdge(e.target.value as 'long' | 'short')}><option value="long">long (85.60 mm)</option><option value="short">short (53.98 mm)</option></select></label>}
      {method === 'tooth' && <label>Measured width (mm) <input inputMode="decimal" value={toothMm} onChange={(e) => setToothMm(e.target.value)} aria-label="Measured tooth width in millimetres" /></label>}
      {method === 'default' && <Banner>This is an assumption, not a measurement. Millimetre values will be labelled ASSUMED.</Banner>}
      {ipdPx ? <div className="row"><button className="secondary" onClick={() => setHyps((x) => [...x, withPlaneUncertainty(fromIpdPrior({ ipdPx, sigmaPx: 1.5 }), 0.08)])}>Add interpupillary-distance prior (assumed 63 ± 3.5 mm, measured {ipdPx.toFixed(0)} px)</button></div> : null}
      <canvas ref={canvas} className="wizard-canvas" onPointerDown={onTap} aria-label="Frozen frame: tap two points" />
      <div className="row"><button onClick={add} disabled={taps.length !== 2}>Add measurement</button><button className="ghost" onClick={() => setTaps([])}>Clear taps</button>{msg && <span role="alert" className="err">{msg}</span>}</div>
      <ul className="hyps">{hyps.map((h, i) => <li key={i}>{h.kind} · {Math.exp(h.u).toFixed(4)} mm/px · σ {(100 * h.sigmaU).toFixed(1)}% <Chip kind={h.status === 'MEASURED' ? 'MEASURED' : 'ASSUMED'}>{h.status}</Chip> <button className="ghost" onClick={() => setHyps((x) => x.filter((_, j) => j !== i))}>Remove</button></li>)}</ul>
      {estimate && <p>Result: <Chip kind={estimate.status === 'METRIC_MEASURED' ? 'OK' : estimate.status === 'METRIC_ASSUMED' ? 'WARN' : 'BAD'}>{estimate.status}</Chip> {estimate.mmPerPx ? `${estimate.mmPerPx.toFixed(4)} mm/px (σ ${(100 * estimate.sigmaU).toFixed(1)}%)` : 'no millimetres: too uncertain or no source'} {estimate.warnings.length ? `· ${estimate.warnings.join(', ')}` : ''}</p>}
      <div className="row"><button disabled={!estimate} onClick={() => estimate && onApply(hyps, estimate)}>Apply</button><button className="secondary" onClick={onClose}>Back</button></div>
    </section>
  );
}
