import { useEffect, useRef, useState } from 'react';
import { KEYPOINT_LAYOUT } from '@core/dental';
import { validateRecord, type LabelRecordV1, type LabelKeypoint, LabelError } from '@core/annotate';
import type { ScaleEstimate } from '@core/scale';
import type { BestFrame } from '../runtime/engine';
import { Banner, download } from './common';

const Z = 5;
const label = (c: number) => { const k = KEYPOINT_LAYOUT[c]!; return `${k.kind}${k.fdi ? ` ${k.fdi}` : k.between ? ` ${k.between[0]}|${k.between[1]}` : ''}`; };

export function Correct({ best, scale, camera, onClose }: { best: BestFrame; scale: ScaleEstimate; camera: string; onClose(): void }) {
  const cv = useRef<HTMLCanvasElement>(null);
  const [kps, setKps] = useState<LabelKeypoint[]>(() => best.analysis.keypoints.map((k) => ({ channel: k.channel, x: k.roiXY?.[0] ?? 0, y: k.roiXY?.[1] ?? 0, visible: k.state === 'ACCEPTED', source: 'network' as const })));
  const [sel, setSel] = useState(0), [pseudo, setPseudo] = useState(''), [annot, setAnnot] = useState(''), [consent, setConsent] = useState(false), [msg, setMsg] = useState<string | null>(null);

  useEffect(() => {
    const c = cv.current, ctx = c?.getContext('2d'); if (!c || !ctx) return;
    c.width = 192 * Z; c.height = 128 * Z;
    const off = document.createElement('canvas'); off.width = 192; off.height = 128; off.getContext('2d')?.putImageData(new ImageData(best.cropRgba, 192, 128), 0, 0);
    ctx.imageSmoothingEnabled = false; ctx.drawImage(off, 0, 0, c.width, c.height);
    kps.forEach((k) => {
      if (!k.visible) return;
      ctx.beginPath(); ctx.arc((k.x + 0.5) * Z, (k.y + 0.5) * Z, k.channel === sel ? 7 : 4, 0, 6.283);
      ctx.fillStyle = k.source === 'network' ? '#22d3ee' : '#facc15'; ctx.fill(); if (k.channel === sel) { ctx.strokeStyle = '#fff'; ctx.lineWidth = 2; ctx.stroke(); }
    });
  }, [kps, sel, best]);

  const place = (e: React.PointerEvent<HTMLCanvasElement>) => {
    const r = e.currentTarget.getBoundingClientRect();
    const x = ((e.clientX - r.left) / r.width) * 192 - 0.5, y = ((e.clientY - r.top) / r.height) * 128 - 0.5;
    setKps((a) => a.map((k) => (k.channel === sel ? { ...k, x, y, visible: true, source: 'clinician' } : k)));
  };
  const exportIt = () => {
    try {
      const c = document.createElement('canvas'); c.width = 192; c.height = 128; c.getContext('2d')?.putImageData(new ImageData(best.cropRgba, 192, 128), 0, 0);
      const rec: LabelRecordV1 = { schema: 'lumina.label/1', id: crypto.randomUUID(), createdAtIso: new Date().toISOString(), consent: { trainingUse: consent as true, version: '1', subjectPseudonym: pseudo },
        device: { camera, width: best.snapshot.width, height: best.snapshot.height }, cropPngBase64: c.toDataURL('image/png').split(',')[1] ?? '', keypoints: kps,
        scale: { status: scale.status, mmPerPx: scale.mmPerPx }, annotator: { id: annot, role: 'clinician' } };
      validateRecord(rec); download(`lumina-label-${rec.id}.json`, JSON.stringify(rec), 'application/json'); setMsg('Exported. Training use requires the consent you just recorded.');
    } catch (e) { setMsg(e instanceof LabelError ? e.message : (e as Error).message); }
  };
  return (
    <section aria-label="Correct keypoints">
      <h2>Review and correct keypoints</h2>
      <Banner tone="info">Cyan = network, yellow = your correction. Select a keypoint, then click the image to place it, or mark it hidden if a lip covers it. Export creates a labelled training record (mouth crop only, no face).</Banner>
      <div className="correct">
        <canvas ref={cv} className="correct-canvas" onPointerDown={place} aria-label="Mouth crop: click to place the selected keypoint" />
        <ul className="kplist" aria-label="Keypoints">{kps.map((k) => <li key={k.channel}><button className={k.channel === sel ? 'sel' : 'ghost'} onClick={() => setSel(k.channel)}>{label(k.channel)} {k.visible ? '' : '(hidden)'}</button></li>)}</ul>
      </div>
      <div className="row">
        <button className="secondary" onClick={() => setKps((a) => a.map((k) => (k.channel === sel ? { ...k, visible: false, source: 'clinician' } : k)))}>Mark selected hidden</button>
        <button className="secondary" onClick={() => setKps((a) => a.map((k) => (k.source === 'network' ? { ...k, source: 'clinician_confirmed' } : k)))}>Confirm all remaining</button>
      </div>
      <fieldset><legend>Export for model training</legend>
        <label>Subject pseudonym (no names) <input value={pseudo} onChange={(e) => setPseudo(e.target.value)} placeholder="S-0042" /></label>
        <label>Annotator ID <input value={annot} onChange={(e) => setAnnot(e.target.value)} /></label>
        <label><input type="checkbox" checked={consent} onChange={(e) => setConsent(e.target.checked)} /> The subject gave written consent for this crop and labels to be used to train and evaluate models.</label>
        <div className="row"><button onClick={exportIt} disabled={!consent || !pseudo || !annot}>Export label record</button><button className="secondary" onClick={onClose}>Back</button></div>
      </fieldset>
      {msg && <p role="status">{msg}</p>}
    </section>
  );
}
