import type { RgbaImage } from '@core/perception/pipeline';
export async function loadDemoImages(fetchFn: typeof fetch = fetch): Promise<RgbaImage[]> {
  const out: RgbaImage[] = [];
  for (let i = 0; i < 4; i++) {
    const r = await fetchFn(`${import.meta.env.BASE_URL}demo/img${i}.png`);
    if (!r.ok) throw new Error(`demo image ${i} missing`);
    const bmp = await createImageBitmap(await r.blob());
    const c = document.createElement('canvas'); c.width = bmp.width; c.height = bmp.height;
    const ctx = c.getContext('2d', { willReadFrequently: true }); if (!ctx) throw new Error('canvas unavailable');
    ctx.drawImage(bmp, 0, 0); out.push(ctx.getImageData(0, 0, bmp.width, bmp.height));
  }
  return out;
}
