import { useEffect, useRef, useState } from 'react';
import { calibrateZhang, locateBoardCorners, type P2, type ZhangResult } from '@core/zhang';
import { classifyIntrinsics } from '@core/calibration';
import { lumaOf, type RgbaImage } from '@core/perception/pipeline';
import type { Services } from '../services';
import type { OpenCamera } from '../runtime/camera';
import { Banner, Chip } from './common';

export interface StoredIntrinsics { fx: number; fy: number; cx: number; cy: number; k1: number; k2: number; relSigmaF: number; rmsPx: number; width: number; height: number; camera: string; savedAtIso: string }
const KEY = 'lumina.intrinsics.v1';
export const loadIntrinsics = (): StoredIntrinsics | null => { try { const s = localStorage.getItem(KEY); return s ? (JSON.parse(s) as StoredIntrinsics) : null; } catch { return null; } };
export const saveIntrinsics = (i: StoredIntrinsics): void => { try { localStorage.setItem(KEY, JSON.stringify(i)); } catch { /* storage unavailable: calibration stays in memory only */ } };

export function Calibrate({ services, deviceId, onSaved, onClose }: { services: Services; deviceId?: string; onSaved(i: StoredIntrinsics): void; onClose(): void }) {
  const video = useRef<HTMLVideoElement>(null), canvas = useRef<HTMLCanvasElement>(null), cam = useRef<OpenCamera | null>(null);
  const [cols, setCols] = useState(9), [rows, setRows] = useState(6), [sq, setSq] = useState('25');
  const [snap, setSnap] = useState<RgbaImage | null>(null), [clicks, setClicks] = useState<P2[]>([]), [found, setFound] = useState<P2[] | null>(null);
  const [views, setViews] = useState<P2[][]>([]), [res, setRes] = useState<ZhangResult | null>(null), [err, setErr] = useState<string | null>(null);

  useEffect(() => {
    let off = false;
    services.openCamera(deviceId).then(async (c) => { if (off) { services.stopCamera(c); return; } cam.current = c; const v = video.current!; v.srcObject = c.stream; await v.play(); }).catch((e) => setErr((e as Error).message));
    return () => { off = true; services.stopCamera(cam.current); };
  }, [services, deviceId]);
  useEffect(() => {
    const c = canvas.current, ctx = c?.getContext('2d'); if (!c || !ctx || !snap) return;
    c.width = snap.width; c.height = snap.height; ctx.putImageData(snap as ImageData, 0, 0);
    ctx.fillStyle = '#22d3ee'; clicks.forEach((p) => { ctx.beginPath(); ctx.arc(p[0], p[1], 5, 0, 6.283); ctx.fill(); });
    ctx.fillStyle = '#facc15'; (found ?? []).forEach((p) => { ctx.beginPath(); ctx.arc(p[0], p[1], 3, 0, 6.283); ctx.fill(); });
  }, [snap, clicks, found]);

  const capture = () => { const v = video.current; if (!v || !v.videoWidth) return; const c = document.createElement('canvas'); c.width = v.videoWidth; c.height = v.videoHeight; const x = c.getContext('2d', { willReadFrequently: true }); if (!x) return; x.drawImage(v, 0, 0); setSnap(x.getImageData(0, 0, c.width, c.height)); setClicks([]); setFound(null); setErr(null); };
  const tap = (e: React.PointerEvent<HTMLCanvasElement>) => {
    if (!snap || found) return; const r = e.currentTarget.getBoundingClientRect();
    const p: P2 = [((e.clientX - r.left) / r.width) * snap.width, ((e.clientY - r.top) / r.height) * snap.height], next = [...clicks, p];
    setClicks(next);
    if (next.length === 4) { const loc = locateBoardCorners(lumaOf(snap), next as [P2, P2, P2, P2], cols, rows); if (loc) setFound(loc.corners); else setErr('Could not find the corners reliably. Retake with better focus/lighting, or click the corners more precisely.'); }
  };
  const accept = () => { if (found) { setViews((v) => [...v, found]); setSnap(null); setClicks([]); setFound(null); } };
  const compute = () => {
    try { const board: P2[] = []; for (let j = 0; j < rows; j++) for (let i = 0; i < cols; i++) board.push([i * Number(sq), j * Number(sq)]); setRes(calibrateZhang(board, views)); setErr(null); } catch (e) { setErr((e as Error).message); }
  };
  const status = res ? classifyIntrinsics('FIDUCIAL_ZHANG', res.relSigmaF) : null;
  const v = video.current;
  return (
    <section aria-label="Camera calibration">
      <h2>Calibrate this camera</h2>
      <Banner tone="info">Print or display a chessboard ({cols + 1}×{rows + 1} squares → {cols}×{rows} inner corners) on a flat surface. Capture at least 5 views with the board tilted differently each time. Click the four outer inner-corners (top-left, top-right, bottom-right, bottom-left); the rest are found automatically. Square size does not affect the intrinsics.</Banner>
      <div className="row">
        <label>Inner corners across <input type="number" min={4} max={20} value={cols} onChange={(e) => setCols(Number(e.target.value))} /></label>
        <label>Inner corners down <input type="number" min={3} max={20} value={rows} onChange={(e) => setRows(Number(e.target.value))} /></label>
        <label>Square size (mm) <input value={sq} inputMode="decimal" onChange={(e) => setSq(e.target.value)} /></label>
      </div>
      {err && <Banner tone="bad" role="alert">{err}</Banner>}
      {!snap ? <><video ref={video} playsInline muted className="stage-video" aria-label="Camera preview" /><div className="row"><button onClick={capture}>Capture view ({views.length} accepted)</button></div></>
        : <><canvas ref={canvas} className="wizard-canvas" onPointerDown={tap} aria-label="Click the four outer corners" /><div className="row"><button onClick={accept} disabled={!found}>Accept this view</button><button className="secondary" onClick={() => { setSnap(null); setFound(null); }}>Discard</button></div></>}
      <div className="row"><button onClick={compute} disabled={views.length < 5}>Compute calibration ({views.length}/5+ views)</button></div>
      {res && status && (
        <div><p>Result <Chip kind={status === 'MEASURED' ? 'OK' : 'WARN'}>{status}</Chip> reprojection rms {res.rmsPx.toFixed(2)} px · fx {res.K.fx.toFixed(1)} ± {res.sigma.fx.toFixed(1)} · fy {res.K.fy.toFixed(1)} · c ({res.K.cx.toFixed(1)}, {res.K.cy.toFixed(1)}) · k1 {res.K.k1.toFixed(3)} · relative σ(f) {(100 * res.relSigmaF).toFixed(2)}%</p>
          {status !== 'MEASURED' && <Banner>Uncertainty is still too high to call these intrinsics measured (needs ≤ 10%). Add views with stronger tilt.</Banner>}
          <button onClick={() => { const s: StoredIntrinsics = { ...res.K, relSigmaF: res.relSigmaF, rmsPx: res.rmsPx, width: v?.videoWidth ?? 0, height: v?.videoHeight ?? 0, camera: cam.current?.label ?? 'camera', savedAtIso: new Date().toISOString() }; saveIntrinsics(s); onSaved(s); }}>Save for this camera</button></div>)}
      <button className="ghost" onClick={onClose}>Back</button>
    </section>
  );
}
