/**
 * Epistemic type layer for LuminaUltra (Sprint S1).
 *
 * Every number the system emits is a Quantity that carries its epistemic class,
 * unit, scale status, uncertainty basis and provenance.
 *
 * Hard rules enforced here:
 *  1. The class of a derived value is the WEAKEST class among its inputs.
 *  2. A value in mm requires a scale; without a scale it is not produced.
 *  3. A model score is never a sigma.
 *  4. sigma may only exist with a sigmaBasis other than 'none'.
 *  5. Missing evidence is a first-class result: INSUFFICIENT_VISUAL_EVIDENCE.
 */

export type Epistemic = 'OBSERVED' | 'MEASURED' | 'INFERRED' | 'ASSUMED' | 'UNKNOWN';
export type Unit = 'px' | 'mm' | 'deg' | 'rad' | 'ratio' | 'rel_depth' | 'none';
export type ScaleStatus = 'METRIC_MEASURED' | 'METRIC_ASSUMED' | 'RELATIVE';
export type SigmaBasis = 'none' | 'propagated' | 'bootstrap' | 'ensemble' | 'empirical_validated';

export interface Provenance {
  stage: string;
  algo: string;
  version: string;
  inputIds: string[];
  frameIds: number[];
}

export interface Quantity<T = number> {
  /** null if and only if status === 'UNKNOWN' */
  value: T | null;
  unit: Unit;
  status: Epistemic;
  /** Required when unit === 'mm'. */
  scaleStatus?: ScaleStatus;
  /** Standard deviation in `unit`. Only present when sigmaBasis !== 'none'. */
  sigma?: number;
  sigmaBasis: SigmaBasis;
  /** Network confidence. NEVER interpreted as accuracy or copied into sigma. */
  modelScore?: number;
  refusal?: 'INSUFFICIENT_VISUAL_EVIDENCE';
  note?: string;
  provenance: Provenance;
}

/** Lower rank = stronger evidence. */
const RANK: Record<Epistemic, number> = {
  OBSERVED: 0,
  MEASURED: 1,
  INFERRED: 2,
  ASSUMED: 3,
  UNKNOWN: 4,
};

/** Weakest-input rule. With no inputs the result is UNKNOWN. */
export function weakest(...classes: Epistemic[]): Epistemic {
  if (classes.length === 0) return 'UNKNOWN';
  let w: Epistemic = 'OBSERVED';
  for (const c of classes) if (RANK[c] > RANK[w]) w = c;
  return w;
}

export function isStrongerOrEqual(a: Epistemic, b: Epistemic): boolean {
  return RANK[a] <= RANK[b];
}

export class EpistemicViolation extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'EpistemicViolation';
  }
}

export interface QuantityInit<T = number> {
  value: T | null;
  unit: Unit;
  status: Epistemic;
  scaleStatus?: ScaleStatus;
  sigma?: number;
  sigmaBasis?: SigmaBasis;
  modelScore?: number;
  note?: string;
  provenance: Provenance;
}

/** Validating constructor. Throws EpistemicViolation if the invariants are broken. */
export function makeQuantity<T = number>(init: QuantityInit<T>): Quantity<T> {
  const basis: SigmaBasis = init.sigmaBasis ?? 'none';
  if (init.status === 'UNKNOWN' && init.value !== null) {
    throw new EpistemicViolation('UNKNOWN quantity must have value === null');
  }
  if (init.status !== 'UNKNOWN' && init.value === null) {
    throw new EpistemicViolation(`${init.status} quantity must have a value`);
  }
  if (init.sigma !== undefined) {
    if (basis === 'none') {
      throw new EpistemicViolation('sigma requires a sigmaBasis other than none');
    }
    if (!Number.isFinite(init.sigma) || init.sigma < 0) {
      throw new EpistemicViolation('sigma must be a finite non-negative number');
    }
  }
  if (init.unit === 'mm' && init.value !== null && init.scaleStatus === undefined) {
    throw new EpistemicViolation('mm quantity requires scaleStatus');
  }
  if (init.unit === 'mm' && init.scaleStatus === 'RELATIVE') {
    throw new EpistemicViolation('RELATIVE scale cannot produce an mm quantity');
  }
  if (init.status === 'MEASURED' && init.scaleStatus === 'METRIC_ASSUMED') {
    throw new EpistemicViolation('MEASURED mm value cannot rest on an assumed scale');
  }
  const q: Quantity<T> = {
    value: init.value,
    unit: init.unit,
    status: init.status,
    sigmaBasis: basis,
    provenance: init.provenance,
  };
  if (init.scaleStatus !== undefined) q.scaleStatus = init.scaleStatus;
  if (init.sigma !== undefined) q.sigma = init.sigma;
  if (init.modelScore !== undefined) q.modelScore = init.modelScore;
  if (init.note !== undefined) q.note = init.note;
  return q;
}

/** A refusal: the stage looked and the evidence is insufficient. */
export function insufficientEvidence<T = number>(
  unit: Unit,
  provenance: Provenance,
  note?: string,
): Quantity<T> {
  const q: Quantity<T> = {
    value: null,
    unit,
    status: 'UNKNOWN',
    sigmaBasis: 'none',
    refusal: 'INSUFFICIENT_VISUAL_EVIDENCE',
    provenance,
  };
  if (note !== undefined) q.note = note;
  return q;
}

/** Ratio of two quantities (dimensionless, so no scale is needed). */
export function ratio(
  num: Quantity,
  den: Quantity,
  provenance: Provenance,
  /** Correlation between num and den errors, in [-1, 1]. Default 0 (independent). */
  correlation = 0,
): Quantity {
  if (num.value === null || den.value === null || den.value === 0) {
    return insufficientEvidence('ratio', provenance, 'numerator or denominator unavailable');
  }
  if (num.unit !== den.unit) {
    throw new EpistemicViolation(`ratio requires matching units, got ${num.unit}/${den.unit}`);
  }
  const r = num.value / den.value;
  const status = weakest(num.status, den.status);
  const init: QuantityInit = { value: r, unit: 'ratio', status, provenance };
  if (num.sigma !== undefined && den.sigma !== undefined) {
    const relN = num.sigma / num.value;
    const relD = den.sigma / den.value;
    const rel2 = relN * relN + relD * relD - 2 * correlation * relN * relD;
    init.sigma = Math.abs(r) * Math.sqrt(Math.max(0, rel2));
    init.sigmaBasis = 'propagated';
  }
  return makeQuantity(init);
}
