import { useEffect, useRef, useState } from 'react';
import { SessionEngine, type LiveUpdate } from '../runtime/engine';
import { CameraSource, DemoSource, type FrameSource } from '../runtime/sources';
import type { LoadedModels } from '../runtime/models';
import type { Services } from '../services';
import type { OpenCamera } from '../runtime/camera';
import { Banner, STEPS, STEP_LABEL, drawOverlay, promptFor } from './common';
import type { FaceTracker } from '../runtime/faceTracker';

export interface Finished { engine: SessionEngine; synthetic: boolean; camera?: string; resolution?: string }
interface Props { mode: 'camera' | 'demo'; models: LoadedModels; services: Services; deviceId?: string; onFinished(f: Finished): void; onCancel(): void }

export function Live({ mode, models, services, deviceId, onFinished, onCancel }: Props) {
  const video = useRef<HTMLVideoElement>(null), overlay = useRef<HTMLCanvasElement>(null), bg = useRef<HTMLCanvasElement>(null);
  const [update, setUpdate] = useState<LiveUpdate | null>(null), [error, setError] = useState<string | null>(null), [loading, setLoading] = useState(true);
  const engineRef = useRef<SessionEngine | null>(null), meta = useRef<Omit<Finished, 'engine'>>({ synthetic: mode === 'demo' });
  const latest = useRef<LiveUpdate | null>(null), dims = useRef({ w: 640, h: 480 }), done = useRef(false);
  const finish = (engine: SessionEngine) => { if (done.current) return; done.current = true; onFinished({ engine, ...meta.current }); };

  useEffect(() => {
    let cancelled = false, cam: OpenCamera | null = null, tracker: FaceTracker | null = null, source: FrameSource | null = null, raf = 0;
    (async () => {
      try {
        const net = await services.createNet(models.dentalNet);
        let images: Awaited<ReturnType<Services['loadDemoImages']>> | null = null, demoData: ImageData | null = null;
        if (mode === 'camera') {
          if (!models.faceTask) throw new Error('The face model is not installed (see README: npm run model:install).');
          tracker = await services.createFaceTracker(models.faceTask);
          cam = await services.openCamera(deviceId);
          const v = video.current!; v.srcObject = cam.stream; await v.play();
          dims.current = { w: v.videoWidth, h: v.videoHeight };
          meta.current = { synthetic: false, camera: cam.label, resolution: `${v.videoWidth}x${v.videoHeight}` };
          source = new CameraSource(v, tracker, cam.label);
        } else {
          images = await services.loadDemoImages(); dims.current = { w: images[0]!.width, h: images[0]!.height }; demoData = new ImageData(new Uint8ClampedArray(images[0]!.data), images[0]!.width, images[0]!.height);
          meta.current = { synthetic: true, camera: 'synthetic demo', resolution: `${dims.current.w}x${dims.current.h}` };
          source = new DemoSource(images);
        }
        if (cancelled) return;
        const engine = new SessionEngine(net, models.gate, source, { stage: 'live', algo: 'lumina-session', version: APP_PROV, inputIds: [], frameIds: [] });
        engineRef.current = engine; setLoading(false);
        const paint = () => {
          raf = requestAnimationFrame(paint);
          const u = latest.current; const o = overlay.current; if (!o) return;
          const w = dims.current.w, h = dims.current.h; if (o.width !== w) { o.width = w; o.height = h; }
          if (mode === 'demo' && bg.current && demoData) { const b = bg.current; if (b.width !== w) { b.width = w; b.height = h; b.getContext('2d')?.putImageData(demoData, 0, 0); } }
          drawOverlay(o, u, w, h);
        };
        raf = requestAnimationFrame(paint);
        await engine.run((u) => { latest.current = u; setUpdate(u); });
        if (!cancelled && engine.step === 'DONE') finish(engine);
      } catch (e) { if (!cancelled) { setError((e as Error).message); setLoading(false); } }
    })();
    return () => { cancelled = true; cancelAnimationFrame(raf); engineRef.current?.stop(); source?.stop(); tracker?.close(); services.stopCamera(cam); };
  }, [mode, models, services, deviceId]); // eslint-disable-line react-hooks/exhaustive-deps

  const cur = update?.step;
  return (
    <section aria-label="Live capture">
      {mode === 'demo' && <Banner tone="info">SYNTHETIC DEMO: generated images stand in for a camera. Nothing here is a patient measurement.</Banner>}
      {error && <Banner tone="bad" role="alert">{error}</Banner>}
      <div className="stage">
        {mode === 'camera' ? <video ref={video} playsInline muted className="mirror" aria-label="Camera preview" /> : <canvas ref={bg} className="bg" />}
        <canvas ref={overlay} className={mode === 'camera' ? 'overlay mirror' : 'overlay'} aria-hidden="true" />
        {loading && !error && <div className="loading">Loading models and camera…</div>}
      </div>
      <p className="prompt" aria-live="polite">{promptFor(update)}</p>
      <ol className="steps">
        {STEPS.map((s) => {
          const idx = STEPS.indexOf(s), curIdx = cur === 'DONE' ? 99 : STEPS.indexOf(cur as (typeof STEPS)[number]);
          const state = idx < curIdx ? 'done' : idx === curIdx ? 'active' : 'todo';
          return <li key={s} className={`step ${state}`}><span>{STEP_LABEL[s]}</span>{state === 'active' && <progress max={1} value={update?.capture?.progress ?? 0} aria-label={`${s} progress`} />}</li>;
        })}
      </ol>
      <p className="stats" aria-label="Statistics">{update ? `${update.fps.toFixed(0)} fps · analysis ${update.analysisMs.toFixed(0)} ms · accepted ${update.accepted} · rejected ${Object.values(update.rejected).reduce((a, b) => a + b, 0)}` : ''}</p>
      {update?.audit && <ul className="audit" aria-label="Self-audit">{[...update.audit.failed.map((c) => ({ ...c, ok: false })), ...(update.audit.failed.length === 0 ? [{ id: 'all checks passing', ok: true, detail: '' }] : [])].map((c) => <li key={c.id} className={c.ok ? 'ok' : 'bad'}>{c.ok ? '✓' : '✗'} {c.id.replace(/_/g, ' ')}{'detail' in c && c.detail ? ` (${c.detail})` : ''}</li>)}</ul>}
      <div className="row">
        <button className="secondary" onClick={() => { engineRef.current?.stop(); if (engineRef.current && update && update.accepted > 0) finish(engineRef.current); else onCancel(); }}>
          {update && update.accepted > 0 ? 'Finish now' : 'Cancel'}
        </button>
        {update && update.accepted > 0 && <button className="ghost" onClick={() => { engineRef.current?.stop(); onCancel(); }}>Discard</button>}
      </div>
    </section>
  );
}
const APP_PROV = '0.1.0';
