/**
 * Scale from user taps on a frozen frame (the workaround for unreliable automatic card detection).
 * Each tap is snapped to the strongest edge along the tap-to-tap axis, then converted to a ScaleHypothesis.
 */
import { locateEdge, sampleProfile, type GrayImage } from './subpixel.js';
import { fromFiducial, fromToothWidth, ID1_WIDTH_MM, ID1_HEIGHT_MM, type ScaleHypothesis } from './scale.js';
import type { Point } from './perception/pipeline.js';

export interface Snapped { p: Point; snapped: boolean; shiftPx: number }

/** Snap `tap` to the strongest edge along direction `dir` within +/- radius px; falls back to the raw tap. */
export function snapEndpoint(g: GrayImage, tap: Point, dir: Point, radius = 8, minStrength = 4): Snapped {
  // the derivative filter needs ~3 px of valid context on each side, so the sampled profile is longer than the search radius
  const e = locateEdge(sampleProfile(g, tap.x, tap.y, dir.x, dir.y, radius + 4, 0.25), { sigmaG: 1.0, minStrength });
  if (e && Math.abs(e.offsetPx) > radius) return { p: tap, snapped: false, shiftPx: 0 };
  if (!e) return { p: tap, snapped: false, shiftPx: 0 };
  const n = Math.hypot(dir.x, dir.y);
  return { p: { x: tap.x + (dir.x / n) * e.offsetPx, y: tap.y + (dir.y / n) * e.offsetPx }, snapped: true, shiftPx: e.offsetPx };
}

export interface PickResult { lengthPx: number; sigmaPx: number; a: Snapped; b: Snapped }
export function pickLength(g: GrayImage, t1: Point, t2: Point): PickResult {
  const dir = { x: t2.x - t1.x, y: t2.y - t1.y };
  if (Math.hypot(dir.x, dir.y) < 20) throw new RangeError('taps are too close together');
  const a = snapEndpoint(g, t1, dir), b = snapEndpoint(g, t2, dir);
  // tap uncertainty: 0.7 px per snapped endpoint, 2 px per unsnapped (hand-placed)
  const sa = a.snapped ? 0.7 : 2, sb = b.snapped ? 0.7 : 2;
  return { lengthPx: Math.hypot(b.p.x - a.p.x, b.p.y - a.p.y), sigmaPx: Math.hypot(sa, sb), a, b };
}

/** Plane mismatch: the card/tooth is not exactly in the incisal plane. Added in quadrature to the log-scale sigma. */
export function withPlaneUncertainty(h: ScaleHypothesis, relSigma = 0.02): ScaleHypothesis {
  return { ...h, sigmaU: Math.hypot(h.sigmaU, relSigma), note: `plane mismatch ${(100 * relSigma).toFixed(0)}% added` };
}

export type CardEdge = 'long' | 'short';
export function hypothesisFromCard(g: GrayImage, t1: Point, t2: Point, edge: CardEdge, tiltDeg = 0, sigmaTiltDeg = 5): ScaleHypothesis {
  const r = pickLength(g, t1, t2);
  return withPlaneUncertainty(fromFiducial({ knownMm: edge === 'long' ? ID1_WIDTH_MM : ID1_HEIGHT_MM, px: r.lengthPx, sigmaPx: r.sigmaPx, tiltDeg, sigmaTiltDeg }), 0.03);
}
export function hypothesisFromMeasuredTooth(g: GrayImage, t1: Point, t2: Point, widthMm: number, sigmaMm = 0.2): ScaleHypothesis {
  if (!(widthMm > 3 && widthMm < 15)) throw new RangeError('tooth width must be between 3 and 15 mm');
  const r = pickLength(g, t1, t2);
  return withPlaneUncertainty(fromToothWidth({ widthMm, sigmaMm, widthPx: r.lengthPx, sigmaPx: r.sigmaPx, measuredByClinician: true, foreshortening: { factor: 1, sigma: 0.03 } }), 0.01);
}
