/**
 * Dental perception: network output CONTRACT and decoder (design section D2).
 *
 * Contract (ONNX, fixed so any backbone can be swapped in):
 *   input  'image' : float32 [1,3,256,384]  RGB mouth ROI, ImageNet-normalised
 *   output 'seg'   : float32 [1,6,256,384]  logits: skin, upper_lip, lower_lip, gingiva, cavity, tooth
 *   output 'ident' : float32 [1,8,256,384]  logits per tooth slot (FDI 14,13,12,11,21,22,23,24); only meaningful on tooth pixels
 *   output 'kp'    : float32 [1,40,64,96]   heatmaps at stride 4, channel order = KEYPOINT_LAYOUT
 *
 * Decoder rules (epistemic):
 *   - Everything decoded here is INFERRED.
 *   - The heatmap peak is a model score: it is stored as modelScore and NEVER as sigma.
 *   - sigma is not emitted from the heatmap spread (that spread is the network's opinion, not an error bound);
 *     it is kept as `heatmapCov` for the ensemble layer and compared with empirical error in benchmarking.
 *   - Weak, multimodal or segmentation-inconsistent peaks are refused.
 */
import { type Provenance, type Quantity, insufficientEvidence, makeQuantity } from './epistemic.js';

export const FDI_SLOTS = [14, 13, 12, 11, 21, 22, 23, 24] as const;
export const SEG_CLASSES = ['skin', 'upper_lip', 'lower_lip', 'gingiva', 'cavity', 'tooth'] as const;
export type KeypointKind = 'incisal_mid' | 'zenith' | 'mesial_corner' | 'distal_corner' | 'papilla' | 'dental_midline';

export interface KeypointChannel { kind: KeypointKind; fdi?: number; between?: [number, number] }

/** 8 teeth x 4 per-tooth keypoints (32), 7 papillae, 1 midline = 40 channels. */
export const KEYPOINT_LAYOUT: KeypointChannel[] = (() => {
  const out: KeypointChannel[] = [];
  for (const f of FDI_SLOTS) for (const kind of ['incisal_mid', 'zenith', 'mesial_corner', 'distal_corner'] as const) out.push({ kind, fdi: f });
  for (let i = 0; i < 7; i++) out.push({ kind: 'papilla', between: [FDI_SLOTS[i] as number, FDI_SLOTS[i + 1] as number] });
  out.push({ kind: 'dental_midline' });
  return out;
})();

export interface HeatmapTensor { data: Float32Array; channels: number; height: number; width: number; stride: number }

/** Maps heatmap-cell coordinates to ORIGINAL image pixels: x_img = x_roi * scale + ox. */
export interface RoiTransform { scale: number; ox: number; oy: number }

export interface DecodedKeypoint {
  channel: number;
  kind: KeypointKind;
  fdi?: number;
  between?: [number, number];
  xy: Quantity<[number, number]>;
  /** [sxx, sxy, syy] of the heatmap mass around the peak, in image px^2. Network opinion, not an error bound. */
  heatmapCov: [number, number, number] | null;
  peak: number;
  reason?: 'WEAK_PEAK' | 'MULTIMODAL' | 'AT_BORDER';
}

export interface DecodeOptions {
  /** Minimum peak value (heatmap in [0,1]) to accept. */
  minPeak?: number;
  /** Half window (cells) for the soft-argmax / moment estimate. */
  halfWindow?: number;
  /** A second peak this fraction of the first, outside the window, marks the channel multimodal. */
  multimodalRatio?: number;
}

export function decodeKeypoints(hm: HeatmapTensor, tf: RoiTransform, prov: Provenance, opt: DecodeOptions = {}): DecodedKeypoint[] {
  const minPeak = opt.minPeak ?? 0.3;
  const hw = opt.halfWindow ?? 3;
  const multi = opt.multimodalRatio ?? 0.6;
  const { channels, height: H, width: W, stride } = hm;
  if (channels !== KEYPOINT_LAYOUT.length) throw new RangeError(`expected ${KEYPOINT_LAYOUT.length} channels, got ${channels}`);
  const out: DecodedKeypoint[] = [];
  for (let c = 0; c < channels; c++) {
    const lay = KEYPOINT_LAYOUT[c] as KeypointChannel;
    const base = c * H * W;
    let best = -Infinity, bi = 0;
    for (let i = 0; i < H * W; i++) { const v = hm.data[base + i] as number; if (v > best) { best = v; bi = i; } }
    const py = Math.floor(bi / W), px = bi % W;
    const mk = (xy: Quantity<[number, number]>, cov: DecodedKeypoint['heatmapCov'], reason?: DecodedKeypoint['reason']): DecodedKeypoint => {
      const d: DecodedKeypoint = { channel: c, kind: lay.kind, xy, heatmapCov: cov, peak: best };
      if (lay.fdi !== undefined) d.fdi = lay.fdi;
      if (lay.between) d.between = lay.between;
      if (reason) d.reason = reason;
      return d;
    };
    if (best < minPeak) { out.push(mk(insufficientEvidence('px', prov, 'weak heatmap peak'), null, 'WEAK_PEAK')); continue; }
    if (px < hw || py < hw || px >= W - hw || py >= H - hw) { out.push(mk(insufficientEvidence('px', prov, 'peak at heatmap border'), null, 'AT_BORDER')); continue; }
    // second mode outside the window?
    let second = 0;
    for (let y = 0; y < H; y++) for (let x = 0; x < W; x++) {
      if (Math.abs(x - px) <= 2 * hw && Math.abs(y - py) <= 2 * hw) continue;
      const v = hm.data[base + y * W + x] as number; if (v > second) second = v;
    }
    if (second >= multi * best) { out.push(mk(insufficientEvidence('px', prov, 'multimodal heatmap'), null, 'MULTIMODAL')); continue; }
    // intensity-weighted centroid and second moments in the window (weights = heatmap - local floor)
    let sw = 0, sx = 0, sy = 0;
    const floor = 0.2 * best;
    for (let dy = -hw; dy <= hw; dy++) for (let dx = -hw; dx <= hw; dx++) {
      const w = Math.max(0, (hm.data[base + (py + dy) * W + (px + dx)] as number) - floor);
      sw += w; sx += w * (px + dx); sy += w * (py + dy);
    }
    const cx = sx / sw, cy = sy / sw;
    let sxx = 0, sxy = 0, syy = 0;
    for (let dy = -hw; dy <= hw; dy++) for (let dx = -hw; dx <= hw; dx++) {
      const w = Math.max(0, (hm.data[base + (py + dy) * W + (px + dx)] as number) - floor);
      sxx += w * (px + dx - cx) ** 2; sxy += w * (px + dx - cx) * (py + dy - cy); syy += w * (py + dy - cy) ** 2;
    }
    // cell centre convention: cell i covers ROI px [i*stride, (i+1)*stride) with centre (i + 0.5) * stride - 0.5
    const roiX = (cx + 0.5) * stride - 0.5, roiY = (cy + 0.5) * stride - 0.5;
    const k = (stride * tf.scale) ** 2;
    out.push(mk(makeQuantity<[number, number]>({
      value: [roiX * tf.scale + tf.ox, roiY * tf.scale + tf.oy], unit: 'px', status: 'INFERRED', modelScore: best, provenance: prov,
    }), [k * sxx / sw, k * sxy / sw, k * syy / sw]));
  }
  return out;
}

/** Segmentation raster used for plausibility checks (class index per pixel, in ROI space). */
export interface ClassMap { data: Uint8Array; width: number; height: number }

const CLS = { skin: 0, upper_lip: 1, lower_lip: 2, gingiva: 3, cavity: 4, tooth: 5 } as const;

/**
 * Cross-check keypoints against the network's own segmentation. A keypoint the segmentation
 * contradicts is refused (e.g. an incisal edge whose neighbourhood is lip, a zenith under the upper lip).
 * `roiXY` is the keypoint in ROI pixels (invert the RoiTransform first).
 */
export function segmentationConsistent(kind: KeypointKind, roiXY: [number, number], cm: ClassMap): boolean {
  const at = (dx: number, dy: number): number => {
    const x = Math.round(roiXY[0] + dx), y = Math.round(roiXY[1] + dy);
    return x < 0 || y < 0 || x >= cm.width || y >= cm.height ? -1 : (cm.data[y * cm.width + x] as number);
  };
  const frac = (offsets: [number, number][], cls: number): number => offsets.filter(([dx, dy]) => at(dx, dy) === cls).length / offsets.length;
  const row = (dy: number): [number, number][] => [-3, 0, 3].map((dx) => [dx, dy] as [number, number]);
  switch (kind) {
    case 'incisal_mid': return frac(row(-3), CLS.tooth) > 0.6 && frac(row(3), CLS.cavity) > 0.5;
    case 'zenith': return frac(row(3), CLS.tooth) > 0.6 && frac(row(-3), CLS.gingiva) > 0.5;
    case 'papilla': return frac([[0, -3], [-3, -3], [3, -3]], CLS.gingiva) > 0.3;
    case 'dental_midline': return frac(row(-3), CLS.tooth) > 0.5;
    default: return frac(row(-3), CLS.tooth) > 0.4; // corners
  }
}

export function invertTransform(xy: [number, number], tf: RoiTransform): [number, number] {
  return [(xy[0] - tf.ox) / tf.scale, (xy[1] - tf.oy) / tf.scale];
}

/** Per-slot visible area (ROI px) from tooth probability and per-slot identity logits. */
export function slotAreas(toothMask: Uint8Array, ident: Float32Array, width: number, height: number, slots = 8): number[] {
  const areas = new Array<number>(slots).fill(0);
  const n = width * height;
  for (let i = 0; i < n; i++) {
    if (!toothMask[i]) continue;
    let b = 0, bv = -Infinity;
    for (let s = 0; s < slots; s++) { const v = ident[s * n + i] as number; if (v > bv) { bv = v; b = s; } }
    areas[b] = (areas[b] as number) + 1;
  }
  return areas;
}
