/**
 * Per-frame measurements from accepted dental keypoints + face geometry (+ optional scale).
 * Scale-free measures (ratios, angles) are always preferred; millimetres are produced only through toMm,
 * i.e. only when a metric scale exists, and carry its status. Every value is INFERRED (network-seeded).
 */
import type { AnalyzedKeypoint, DentalAnalysis } from './perception/pipeline.js';
import { NET_W, NET_H } from './perception/pipeline.js';
import { type Provenance, type Quantity, insufficientEvidence, makeQuantity, ratio } from './epistemic.js';
import { type ScaleEstimate, toMm } from './scale.js';
import { FDI_SLOTS } from './dental.js';
import type { FaceGeometry } from './face.js';

export type MeasureId =
  | 'midline_deviation' | 'incisal_cant_deg' | 'wl_ratio_11' | 'wl_ratio_21' | 'width_ratio_21_over_11'
  | 'gingival_display_ratio' | 'visible_teeth_count' | 'width_11_mm' | 'width_21_mm' | 'midline_deviation_mm'
  | 'width_11_px' | 'width_21_px' | 'midline_offset_px';

const kp = (a: DentalAnalysis, kind: string, fdi?: number): AnalyzedKeypoint | undefined =>
  a.keypoints.find((k) => k.kind === kind && k.state === 'ACCEPTED' && (fdi === undefined || k.fdi === fdi));

const q = (value: number, unit: 'px' | 'deg' | 'ratio' | 'none', prov: Provenance, note?: string): Quantity =>
  makeQuantity({ value, unit, status: 'INFERRED', provenance: prov, ...(note ? { note } : {}) });

/** Apparent crown width (image px) of a tooth slot at mid-height: widest contiguous run through its column. */
export function slotWidthAtMidHeight(a: DentalAnalysis, fdi: number): { px: number; yMid: number } | null {
  const slot = FDI_SLOTS.indexOf(fdi as (typeof FDI_SLOTS)[number]);
  const inc = kp(a, 'incisal_mid', fdi), zen = kp(a, 'zenith', fdi);
  if (slot < 0 || !inc || !zen || !inc.roiXY || !zen.roiXY) return null;
  const yMid = Math.round((inc.roiXY[1] + zen.roiXY[1]) / 2), xc = Math.round(inc.roiXY[0]);
  if (yMid < 0 || yMid >= NET_H || xc < 0 || xc >= NET_W) return null;
  const at = (x: number) => a.slotMap[yMid * NET_W + x] === slot;
  if (!at(xc)) return null;
  let l = xc, r = xc;
  while (l > 0 && at(l - 1)) l--;
  while (r < NET_W - 1 && at(r + 1)) r++;
  if (l === 0 || r === NET_W - 1) return null; // truncated by the crop
  return { px: (r - l + 1) * a.tf.scale, yMid };
}

function heightPx(a: DentalAnalysis, fdi: number): number | null {
  const inc = kp(a, 'incisal_mid', fdi), zen = kp(a, 'zenith', fdi);
  return inc?.xy.value && zen?.xy.value ? Math.hypot(inc.xy.value[0] - zen.xy.value[0], inc.xy.value[1] - zen.xy.value[1]) : null;
}

/** Distance (image px) from the zenith up to the lower margin of the upper lip along the tooth axis, 0 if no gingiva shows. */
function gingivalDisplayPx(a: DentalAnalysis, fdi: number): number | null {
  const zen = kp(a, 'zenith', fdi);
  if (!zen?.roiXY) return null;
  const x = Math.round(zen.roiXY[0]);
  let y = Math.round(zen.roiXY[1]) - 2, run = 0;
  while (y >= 0) {
    const c = a.classMap[y * NET_W + x];
    if (c === 3) run++; else if (c === 1) return run * a.tf.scale; else if (c === 5 || c === 4) return null; else if (c === 0) return null;
    y--;
  }
  return null; // reached the crop top without finding the lip
}

export function measureFrame(a: DentalAnalysis, face: FaceGeometry, scale: ScaleEstimate, prov: Provenance): Partial<Record<MeasureId, Quantity>> {
  const out: Partial<Record<MeasureId, Quantity>> = {};
  const refuse = (id: MeasureId, unit: 'px' | 'deg' | 'ratio' | 'none', why: string) => { out[id] = insufficientEvidence(unit, prov, why); };
  out.visible_teeth_count = q(a.slotAreas.filter((v) => v >= 60).length, 'none', prov);

  const w11 = slotWidthAtMidHeight(a, 11), w21 = slotWidthAtMidHeight(a, 21);
  const h11 = heightPx(a, 11), h21 = heightPx(a, 21);
  if (w11 && h11) out.wl_ratio_11 = q(w11.px / h11, 'ratio', prov, 'apparent crown width at mid-height / zenith-to-incisal height'); else refuse('wl_ratio_11', 'ratio', 'tooth 11 width/height not observable');
  if (w21 && h21) out.wl_ratio_21 = q(w21.px / h21, 'ratio', prov, 'apparent crown width at mid-height / zenith-to-incisal height'); else refuse('wl_ratio_21', 'ratio', 'tooth 21 width/height not observable');
  if (w11) out.width_11_px = q(w11.px, 'px', prov, 'apparent crown width at mid-height, source-frame pixels');
  if (w21) out.width_21_px = q(w21.px, 'px', prov, 'apparent crown width at mid-height, source-frame pixels');
  if (w11 && w21) out.width_ratio_21_over_11 = q(w21.px / w11.px, 'ratio', prov); else refuse('width_ratio_21_over_11', 'ratio', 'both central incisor widths needed');

  const mid = kp(a, 'dental_midline');
  if (mid?.xy.value) {
    const dxPx = mid.xy.value[0] - face.midlineXAt(mid.xy.value[1]);
    const pxQ = q(dxPx, 'px', prov, 'dental midline minus facial midline (+ = toward image right); facial midline from a landmark line extrapolated to the mouth');
    out.midline_offset_px = pxQ;
    if (scale.status !== 'RELATIVE') out.midline_deviation_mm = toMm(pxQ, scale, prov);
    if (w11 && w21) out.midline_deviation = ratio(pxQ, q((w11.px + w21.px) / 2, 'px', prov), prov); // dimensionless: fraction of central width
    else refuse('midline_deviation', 'ratio', 'central incisor widths needed to normalise without a metric scale');
  } else { refuse('midline_deviation', 'ratio', 'dental midline not visible'); }

  const pair = ([[13, 23], [12, 22], [14, 24]] as const).map(([r, l]) => [kp(a, 'incisal_mid', r), kp(a, 'incisal_mid', l)] as const).find(([r, l]) => r?.xy.value && l?.xy.value);
  if (pair) {
    const [r, l] = pair as [AnalyzedKeypoint, AnalyzedKeypoint];
    const ang = (Math.atan2(l.xy.value![1] - r.xy.value![1], l.xy.value![0] - r.xy.value![0]) * 180) / Math.PI;
    out.incisal_cant_deg = q(ang - face.eyeLineDeg, 'deg', prov, 'incisal-edge line relative to the eye line (roll-invariant)');
  } else refuse('incisal_cant_deg', 'deg', 'a symmetric pair of incisal edges is not visible');

  const g = [11, 21].map((f) => ({ d: gingivalDisplayPx(a, f), h: heightPx(a, f) })).filter((v): v is { d: number; h: number } => v.d !== null && v.h !== null);
  if (g.length) out.gingival_display_ratio = q(g.reduce((s, v) => s + v.d / v.h, 0) / g.length, 'ratio', prov, 'gingiva visible above the zenith / crown height; 0 = none');
  else refuse('gingival_display_ratio', 'ratio', 'zenith or lip margin not visible');

  for (const [id, w] of [['width_11_mm', w11], ['width_21_mm', w21]] as const) {
    if (w && scale.status !== 'RELATIVE') out[id] = toMm(q(w.px, 'px', prov), scale, prov);
  }
  return out;
}
