/** Frame-quality primitives for the capture gates (pure, testable). */
import type { GrayImage } from './subpixel.js';
import type { Point } from './perception/pipeline.js';

/**
 * Noise-compensated sharpness: variance of the 4-neighbour Laplacian over the region (on 2x2 block means) minus a robust
 * estimate of its noise-only variance, so sensor noise does not masquerade as sharpness (higher = sharper, 0 = no detail). Thresholds are camera-dependent and must be tuned on real devices.
 */
export function laplacianVariance(g: GrayImage, x0: number, y0: number, x1: number, y1: number): number {
  const xa = Math.max(0, Math.floor(x0)), ya = Math.max(0, Math.floor(y0));
  const cw = Math.floor((Math.min(g.width, Math.ceil(x1)) - xa) / 2), ch = Math.floor((Math.min(g.height, Math.ceil(y1)) - ya) / 2);
  if (cw < 4 || ch < 4) return 0;
  const c = new Float32Array(cw * ch);
  for (let j = 0; j < ch; j++) for (let i = 0; i < cw; i++) {
    const x = xa + 2 * i, y = ya + 2 * j;
    c[j * cw + i] = 0.25 * ((g.data[y * g.width + x] as number) + (g.data[y * g.width + x + 1] as number) + (g.data[(y + 1) * g.width + x] as number) + (g.data[(y + 1) * g.width + x + 1] as number));
  }
  let n = 0, s = 0, s2 = 0;
  const ls: number[] = [];
  for (let j = 1; j < ch - 1; j++) for (let i = 1; i < cw - 1; i++) {
    const k = j * cw + i, l = 4 * (c[k] as number) - (c[k - 1] as number) - (c[k + 1] as number) - (c[k - cw] as number) - (c[k + cw] as number);
    n++; s += l; s2 += l * l; if ((i + j) % 2 === 0) ls.push(l);
  }
  const variance = s2 / n - (s / n) ** 2;
  // noise floor: robust (MAD) estimate of the Laplacian spread, which edges barely affect because they are sparse
  ls.sort((a, b) => a - b);
  const med = ls[ls.length >> 1] as number, dev = ls.map((v) => Math.abs(v - med)).sort((a, b) => a - b);
  const sigmaL = 1.4826 * (dev[dev.length >> 1] as number);
  return Math.max(0, variance - sigmaL * sigmaL);
}

export function lumaStats(g: GrayImage, x0: number, y0: number, x1: number, y1: number, clipAt = 250): { mean: number; clipFraction: number } {
  const xa = Math.max(0, Math.floor(x0)), xb = Math.min(g.width, Math.ceil(x1)), ya = Math.max(0, Math.floor(y0)), yb = Math.min(g.height, Math.ceil(y1));
  let n = 0, s = 0, c = 0;
  for (let y = ya; y < yb; y++) for (let x = xa; x < xb; x++) { const v = g.data[y * g.width + x] as number; n++; s += v; if (v >= clipAt) c++; }
  return n === 0 ? { mean: 0, clipFraction: 0 } : { mean: s / n, clipFraction: c / n };
}

/** Mean displacement (px) of tracked rigid points between two frames; Infinity if the sets differ in size. */
export function meanMotion(prev: Point[] | null, cur: Point[]): number {
  if (!prev || prev.length !== cur.length || cur.length === 0) return 0;
  let s = 0;
  for (let i = 0; i < cur.length; i++) s += Math.hypot((cur[i] as Point).x - (prev[i] as Point).x, (cur[i] as Point).y - (prev[i] as Point).y);
  return s / cur.length;
}
