/**
 * Multi-hypothesis Bayesian scale estimation (design section D7).
 *
 * Works in log space: u = ln(mm per pixel at the incisal plane).
 *
 * Policy (deliberately conservative):
 *  - Only MEASURED hypotheses (clinician-measured tooth width, reference fiducial)
 *    can establish METRIC_MEASURED scale.
 *  - ASSUMED hypotheses (population tooth width, IPD prior) are correlated within a
 *    subject, so they are NOT multiplied together: their pooled sigma is the smallest
 *    member sigma. They only produce METRIC_ASSUMED, and serve as a conflict check
 *    against measured evidence.
 *  - If the achievable relative sigma is above the gate, the result degrades to
 *    RELATIVE (no millimetres) instead of reporting an unsupported number.
 */
import {
  type Provenance,
  type Quantity,
  type QuantityInit,
  type ScaleStatus,
  insufficientEvidence,
  makeQuantity,
  weakest,
} from './epistemic.js';

export type HypothesisKind = 'TOOTH_MEASURED' | 'TOOTH_DEFAULT' | 'FIDUCIAL' | 'IPD_PRIOR';

export interface ScaleHypothesis {
  kind: HypothesisKind;
  /** ln(mm/px) at the reference plane of this hypothesis. */
  u: number;
  sigmaU: number;
  status: 'MEASURED' | 'ASSUMED';
  note?: string;
}

export const ID1_WIDTH_MM = 85.6; // ISO/IEC 7810 ID-1 card
export const ID1_HEIGHT_MM = 53.98;
export const DEFAULT_CENTRAL_INCISOR_MM = 8.5; // population value: ASSUMED
export const DEFAULT_CENTRAL_INCISOR_SIGMA_MM = 0.7;
export const DEFAULT_IPD_MM = 63; // adult mean: ASSUMED
export const DEFAULT_IPD_SIGMA_MM = 3.5;

function assertPositive(name: string, v: number): void {
  if (!Number.isFinite(v) || v <= 0) throw new RangeError(`${name} must be a positive finite number`);
}

export interface ToothWidthInput {
  /** True mesiodistal width in mm. */
  widthMm: number;
  sigmaMm: number;
  /** Observed projected width in image pixels. */
  widthPx: number;
  sigmaPx: number;
  /** true if a clinician measured THIS tooth (caliper, scan). false = population default. */
  measuredByClinician: boolean;
  /** projected/true width ratio from arch curvature and yaw. Default 1 (frontal, central incisor). */
  foreshortening?: { factor: number; sigma: number };
}

export function fromToothWidth(i: ToothWidthInput): ScaleHypothesis {
  assertPositive('widthMm', i.widthMm);
  assertPositive('widthPx', i.widthPx);
  const f = i.foreshortening?.factor ?? 1;
  const sf = i.foreshortening?.sigma ?? 0;
  assertPositive('foreshortening.factor', f);
  const projectedMm = i.widthMm * f;
  const relMm2 = (i.sigmaMm / i.widthMm) ** 2 + (sf / f) ** 2;
  const relPx2 = (i.sigmaPx / i.widthPx) ** 2;
  return {
    kind: i.measuredByClinician ? 'TOOTH_MEASURED' : 'TOOTH_DEFAULT',
    u: Math.log(projectedMm / i.widthPx),
    sigmaU: Math.sqrt(relMm2 + relPx2),
    status: i.measuredByClinician ? 'MEASURED' : 'ASSUMED',
  };
}

export interface FiducialInput {
  /** Known edge length of the fiducial, mm (e.g. ID1_WIDTH_MM). */
  knownMm: number;
  sigmaMm?: number;
  /** Observed length of that edge in px. */
  px: number;
  sigmaPx: number;
  /** Tilt of the fiducial plane relative to the image plane (foreshortening = cos). */
  tiltDeg?: number;
  sigmaTiltDeg?: number;
}

export function fromFiducial(i: FiducialInput): ScaleHypothesis {
  assertPositive('knownMm', i.knownMm);
  assertPositive('px', i.px);
  const tilt = ((i.tiltDeg ?? 0) * Math.PI) / 180;
  const sTilt = ((i.sigmaTiltDeg ?? 0) * Math.PI) / 180;
  const projectedMm = i.knownMm * Math.cos(tilt);
  assertPositive('cos(tilt)', projectedMm);
  const relMm2 = ((i.sigmaMm ?? 0.1) / i.knownMm) ** 2;
  const relTilt2 = (Math.tan(tilt) * sTilt) ** 2; // d ln cos = -tan * d tilt
  const relPx2 = (i.sigmaPx / i.px) ** 2;
  return {
    kind: 'FIDUCIAL',
    u: Math.log(projectedMm / i.px),
    sigmaU: Math.sqrt(relMm2 + relTilt2 + relPx2),
    status: 'MEASURED',
  };
}

export interface IpdInput {
  ipdPx: number;
  sigmaPx: number;
  ipdMm?: number;
  sigmaMm?: number;
}

export function fromIpdPrior(i: IpdInput): ScaleHypothesis {
  assertPositive('ipdPx', i.ipdPx);
  const mm = i.ipdMm ?? DEFAULT_IPD_MM;
  const sMm = i.sigmaMm ?? DEFAULT_IPD_SIGMA_MM;
  return {
    kind: 'IPD_PRIOR',
    u: Math.log(mm / i.ipdPx),
    sigmaU: Math.sqrt((sMm / mm) ** 2 + (i.sigmaPx / i.ipdPx) ** 2),
    status: 'ASSUMED',
  };
}

export interface PlaneTransfer {
  /** Camera-to-reference-plane distance, mm. Itself uncertain. */
  distanceMm: number;
  sigmaDistanceMm: number;
  /** Signed depth of the target plane relative to the reference plane (+ = farther). */
  planeOffsetMm: number;
  sigmaOffsetMm: number;
}

/**
 * mm/px is proportional to depth: s(Z) = Z / f.
 * Moving a scale from a reference plane at Z to a target plane at Z + dz adds ln(1 + dz/Z).
 */
export function transferToPlane(h: ScaleHypothesis, t: PlaneTransfer): ScaleHypothesis {
  assertPositive('distanceMm', t.distanceMm);
  const Z = t.distanceMm;
  const dz = t.planeOffsetMm;
  if (Z + dz <= 0) throw new RangeError('target plane is behind the camera');
  const dUdZ = 1 / (Z + dz) - 1 / Z;
  const dUddz = 1 / (Z + dz);
  const extra2 = (dUdZ * t.sigmaDistanceMm) ** 2 + (dUddz * t.sigmaOffsetMm) ** 2;
  return {
    ...h,
    u: h.u + Math.log((Z + dz) / Z),
    sigmaU: Math.sqrt(h.sigmaU ** 2 + extra2),
    note: 'plane-transferred',
  };
}

export interface ScaleEstimate {
  status: ScaleStatus;
  /** ln(mm/px). NaN when status === 'RELATIVE' and nothing was usable. */
  u: number;
  sigmaU: number;
  mmPerPx: number | null;
  sigmaMmPerPx: number | null;
  used: ScaleHypothesis[];
  chi2: number;
  dof: number;
  /** Birge ratio applied to the variance (>= 1). */
  inflation: number;
  warnings: string[];
}

export interface EstimateOptions {
  /** Maximum relative sigma (sigmaU) for a metric status. Default 0.05 (5%). */
  maxRelSigma?: number;
  /** z-score beyond which assumed priors are flagged as conflicting with measured evidence. */
  conflictZ?: number;
}

interface Combined {
  u: number;
  variance: number;
  chi2: number;
  dof: number;
}

function precisionWeighted(list: ScaleHypothesis[]): Combined {
  let sw = 0;
  let swu = 0;
  for (const h of list) {
    const w = 1 / (h.sigmaU * h.sigmaU);
    sw += w;
    swu += w * h.u;
  }
  const u = swu / sw;
  let chi2 = 0;
  for (const h of list) chi2 += ((h.u - u) / h.sigmaU) ** 2;
  return { u, variance: 1 / sw, chi2, dof: list.length - 1 };
}

export function estimateScale(hyps: ScaleHypothesis[], opts: EstimateOptions = {}): ScaleEstimate {
  const maxRel = opts.maxRelSigma ?? 0.05;
  const conflictZ = opts.conflictZ ?? 3;
  const warnings: string[] = [];
  for (const h of hyps) {
    if (!(h.sigmaU > 0) || !Number.isFinite(h.u)) {
      throw new RangeError(`invalid hypothesis ${h.kind}: u and sigmaU must be finite, sigmaU > 0`);
    }
  }
  const measured = hyps.filter((h) => h.status === 'MEASURED');
  const assumed = hyps.filter((h) => h.status === 'ASSUMED');

  let assumedPool: { u: number; variance: number } | null = null;
  if (assumed.length > 0) {
    const p = precisionWeighted(assumed);
    // correlated within subject: no variance reduction from averaging
    assumedPool = { u: p.u, variance: Math.min(...assumed.map((h) => h.sigmaU ** 2)) };
  }

  const relative = (why: string, used: ScaleHypothesis[]): ScaleEstimate => ({
    status: 'RELATIVE',
    u: Number.NaN,
    sigmaU: Number.NaN,
    mmPerPx: null,
    sigmaMmPerPx: null,
    used,
    chi2: 0,
    dof: 0,
    inflation: 1,
    warnings: [...warnings, why],
  });

  if (measured.length === 0 && assumedPool === null) {
    return relative('no_scale_source', []);
  }

  if (measured.length > 0) {
    const c = precisionWeighted(measured);
    const inflation = c.dof > 0 ? Math.max(1, c.chi2 / c.dof) : 1;
    if (inflation > 1) warnings.push('measured_hypotheses_inconsistent');
    const variance = c.variance * inflation;
    const sigmaU = Math.sqrt(variance);
    if (assumedPool) {
      const z = Math.abs(c.u - assumedPool.u) / Math.sqrt(variance + assumedPool.variance);
      if (z > conflictZ) warnings.push('assumed_prior_conflicts_with_measured');
    }
    if (sigmaU > maxRel) {
      return {
        ...relative('scale_too_uncertain_for_mm', measured),
        u: c.u,
        sigmaU,
        chi2: c.chi2,
        dof: c.dof,
        inflation,
      };
    }
    const mm = Math.exp(c.u);
    return {
      status: 'METRIC_MEASURED',
      u: c.u,
      sigmaU,
      mmPerPx: mm,
      sigmaMmPerPx: mm * sigmaU,
      used: measured,
      chi2: c.chi2,
      dof: c.dof,
      inflation,
      warnings,
    };
  }

  // assumed-only
  const a = assumedPool!;
  const sigmaU = Math.sqrt(a.variance);
  warnings.push('scale_is_assumed_not_measured');
  const mm = Math.exp(a.u);
  return {
    status: 'METRIC_ASSUMED',
    u: a.u,
    sigmaU,
    mmPerPx: mm,
    sigmaMmPerPx: mm * sigmaU,
    used: assumed,
    chi2: 0,
    dof: 0,
    inflation: 1,
    warnings,
  };
}

/**
 * Convert a pixel length into millimetres, honouring the epistemic rules.
 *  - RELATIVE scale: refuses (use ratios instead).
 *  - Class = weakest(pixel class, scale class). An INFERRED landmark distance stays INFERRED.
 *  - sigma is propagated only if the pixel quantity has one; scale sigma is added in quadrature.
 */
export function toMm(px: Quantity, scale: ScaleEstimate, provenance: Provenance): Quantity {
  if (px.unit !== 'px') throw new TypeError(`toMm expects px, got ${px.unit}`);
  if (px.value === null) return insufficientEvidence('mm', provenance, 'pixel quantity unavailable');
  if (scale.status === 'RELATIVE' || scale.mmPerPx === null) {
    return insufficientEvidence('mm', provenance, 'no metric scale: report ratios, not millimetres');
  }
  const scaleClass = scale.status === 'METRIC_MEASURED' ? 'MEASURED' : 'ASSUMED';
  const status = weakest(px.status, scaleClass);
  const value = px.value * scale.mmPerPx;
  const init: QuantityInit = {
    value,
    unit: 'mm',
    status,
    scaleStatus: scale.status,
    provenance,
  };
  if (px.sigma !== undefined) {
    const rel2 = (px.sigma / px.value) ** 2 + scale.sigmaU ** 2;
    init.sigma = Math.abs(value) * Math.sqrt(rel2);
    init.sigmaBasis = 'propagated';
  }
  if (scale.status === 'METRIC_ASSUMED') init.note = 'assumed scale: not a measurement';
  return makeQuantity(init);
}
