/** Session report: twin JSON + a self-contained, XSS-safe HTML document. No external resources are referenced. */
import { type Quantity } from './epistemic.js';
import { TwinBuilder, describe, type TwinState } from './twin.js';
import type { ScaleEstimate } from './scale.js';

export const MEASURE_LABELS: Record<string, string> = {
  midline_deviation: 'Dental midline offset from facial midline (fraction of central width)',
  midline_deviation_mm: 'Dental midline offset from facial midline',
  incisal_cant_deg: 'Incisal-edge cant relative to eye line',
  wl_ratio_11: 'Width / length ratio, tooth 11', wl_ratio_21: 'Width / length ratio, tooth 21',
  width_ratio_21_over_11: 'Central incisor width ratio (21 / 11)',
  gingival_display_ratio: 'Gingival display (fraction of crown height)',
  visible_teeth_count: 'Visible teeth in smile', midline_offset_px: 'Dental midline offset (source pixels)', width_11_px: 'Apparent crown width, tooth 11 (pixels)', width_21_px: 'Apparent crown width, tooth 21 (pixels)', width_11_mm: 'Apparent crown width, tooth 11', width_21_mm: 'Apparent crown width, tooth 21',
};

export interface SessionInput {
  id: string; createdAtIso: string; label: string; appVersion: string;
  device: { camera?: string; resolution?: string; userAgent?: string };
  models: { dentalNet: string; gate: string; face: string };
  scale: Pick<ScaleEstimate, 'status' | 'mmPerPx' | 'sigmaU' | 'warnings'>;
  frames: { accepted: number; rejected: Record<string, number> };
  results: Record<string, Quantity>;
  intrinsics?: { status: 'MEASURED' | 'ASSUMED'; source: string; fx: number; relSigmaF: number; rmsPx?: number };
}

export function esc(s: string): string {
  return s.replace(/[&<>"'`]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;', '`': '&#96;' })[c] as string);
}

export function buildTwin(s: SessionInput): TwinState {
  const t = new TwinBuilder(s.id);
  for (const [id, q] of Object.entries(s.results)) t.add(id, q as Quantity<number | number[]>);
  const twin = t.build();
  if (s.scale.status === 'RELATIVE') twin.warnings.push('no metric scale: millimetre values are not reported');
  if (s.scale.status === 'METRIC_ASSUMED') twin.warnings.push('scale rests on an assumed population value, not a measurement');
  for (const w of s.scale.warnings) twin.warnings.push(`scale: ${w}`);
  return twin;
}

export function buildReportHtml(s: SessionInput): string {
  const twin = buildTwin(s);
  const rows = Object.entries(s.results).map(([id, q]) => {
    const label = MEASURE_LABELS[id] ?? id;
    if (q.value === null) return `<tr class="na"><td>${esc(label)}</td><td colspan="4">Not reported: ${esc(q.note ?? q.refusal ?? 'insufficient visual evidence')}</td></tr>`;
    const v = typeof q.value === 'number' ? q.value.toFixed(q.unit === 'ratio' ? 3 : 2) : esc(String(q.value));
    const sig = q.sigma !== undefined ? `± ${q.sigma.toFixed(q.unit === 'ratio' ? 3 : 2)} <small>(${esc(q.sigmaBasis)}: precision only)</small>` : '<small>relative estimate only</small>';
    const sc = q.unit === 'mm' ? ` <small>[${esc(q.scaleStatus ?? '?')}]</small>` : '';
    return `<tr><td>${esc(label)}</td><td>${v} ${esc(q.unit)}${sc}</td><td>${sig}</td><td><span class="c ${esc(q.status)}">${esc(q.status)}</span></td><td><small>${esc(q.note ?? '')}</small></td></tr>`;
  }).join('');
  const rej = Object.entries(s.frames.rejected).map(([k, n]) => `${esc(k)}: ${n}`).join(', ') || 'none';
  const scaleLine = s.scale.status === 'RELATIVE' ? 'None established: ratios and angles only.' :
    `${esc(s.scale.status)}: ${(s.scale.mmPerPx ?? 0).toFixed(4)} mm/px (relative σ ${(100 * s.scale.sigmaU).toFixed(1)}%).`;
  return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Smile analysis report ${esc(s.id)}</title><style>
body{font:14px/1.5 system-ui,sans-serif;margin:2rem auto;max-width:60rem;padding:0 1rem;color:#1b1f23}
h1{font-size:1.4rem}.banner{border:2px solid #b45309;background:#fffbeb;padding:.75rem 1rem;border-radius:.5rem;margin:1rem 0}
table{border-collapse:collapse;width:100%;margin:1rem 0}td,th{border-bottom:1px solid #ddd;padding:.4rem .5rem;text-align:left;vertical-align:top}
tr.na td{color:#6b7280}.c{padding:.1rem .4rem;border-radius:.3rem;background:#e5e7eb;font-size:.75rem}.c.INFERRED{background:#dbeafe}.c.ASSUMED{background:#fde68a}.c.MEASURED{background:#bbf7d0}
small{color:#4b5563}@media print{.noprint{display:none}}</style></head><body>
<h1>Smile analysis report</h1>
<div class="banner"><strong>Research prototype, not validated for clinical decisions.</strong> Values are estimates from a webcam image and a neural network trained on synthetic data. Uncertainties describe frame-to-frame repeatability, not accuracy. Confirm with direct clinical measurement.</div>
<p><strong>Session:</strong> ${esc(s.id)} &middot; ${esc(s.createdAtIso)} &middot; <strong>Label:</strong> ${esc(s.label)}<br>
<strong>Scale:</strong> ${scaleLine}<br><strong>Camera intrinsics:</strong> ${s.intrinsics ? `${esc(s.intrinsics.status)} (${esc(s.intrinsics.source)}; fx ${s.intrinsics.fx.toFixed(0)} px, relative sigma ${(100 * s.intrinsics.relSigmaF).toFixed(1)}%${s.intrinsics.rmsPx !== undefined ? `, reprojection rms ${s.intrinsics.rmsPx.toFixed(2)} px` : ''})` : 'ASSUMED prior (never calibrated for this camera)'}<br><strong>Frames accepted:</strong> ${s.frames.accepted} &middot; <strong>Rejected:</strong> ${rej}</p>
<table><thead><tr><th>Measurement</th><th>Value</th><th>Uncertainty</th><th>Class</th><th>Notes</th></tr></thead><tbody>${rows}</tbody></table>
${twin.warnings.length ? `<h2>Warnings</h2><ul>${twin.warnings.map((w) => `<li>${esc(w)}</li>`).join('')}</ul>` : ''}
<h2>Provenance</h2><p><small>App ${esc(s.appVersion)} &middot; dental net ${esc(s.models.dentalNet)} &middot; gate ${esc(s.models.gate)} &middot; face model ${esc(s.models.face)} &middot; camera ${esc(s.device.camera ?? 'unknown')} ${esc(s.device.resolution ?? '')}</small></p>
</body></html>`;
}

export function describeAll(results: Record<string, Quantity>): string[] {
  return Object.entries(results).map(([id, q]) => describe(MEASURE_LABELS[id] ?? id, q as Quantity<number | number[]>));
}
