/**
 * Subpixel edge localisation (design section D3).
 *
 * Intensity profile along the edge normal -> Gaussian-derivative filter ->
 * |gradient| peak -> three-point parabola refinement. This recovers only what the
 * pixels support: if contrast is too low or the peak is not interior, it returns null
 * rather than guessing.
 */

export interface GrayImage {
  data: Float32Array | Uint8Array | Uint8ClampedArray;
  width: number;
  height: number;
}

/** Bilinear sample; returns NaN outside the image (never extrapolates). */
export function sampleBilinear(img: GrayImage, x: number, y: number): number {
  if (x < 0 || y < 0 || x > img.width - 1 || y > img.height - 1) return Number.NaN;
  const x0 = Math.floor(x);
  const y0 = Math.floor(y);
  const x1 = Math.min(x0 + 1, img.width - 1);
  const y1 = Math.min(y0 + 1, img.height - 1);
  const fx = x - x0;
  const fy = y - y0;
  const w = img.width;
  const d = img.data;
  const a = d[y0 * w + x0] as number;
  const b = d[y0 * w + x1] as number;
  const c = d[y1 * w + x0] as number;
  const e = d[y1 * w + x1] as number;
  return a * (1 - fx) * (1 - fy) + b * fx * (1 - fy) + c * (1 - fx) * fy + e * fx * fy;
}

export interface Profile {
  values: Float32Array;
  /** Distance along the normal of sample k is (k - half) * step. */
  half: number;
  step: number;
}

/** Sample 2*halfLen/step + 1 points along unit normal (nx, ny) through (cx, cy). */
export function sampleProfile(
  img: GrayImage,
  cx: number,
  cy: number,
  nx: number,
  ny: number,
  halfLen = 6,
  step = 0.25,
): Profile {
  const norm = Math.hypot(nx, ny);
  if (!(norm > 0)) throw new RangeError('normal must be non-zero');
  const ux = nx / norm;
  const uy = ny / norm;
  const half = Math.round(halfLen / step);
  const values = new Float32Array(2 * half + 1);
  for (let k = 0; k < values.length; k++) {
    const t = (k - half) * step;
    values[k] = sampleBilinear(img, cx + ux * t, cy + uy * t);
  }
  return { values, half, step };
}

export interface EdgeResult {
  /** Signed offset from the profile centre along the normal, in pixels. */
  offsetPx: number;
  /** Peak gradient magnitude, intensity units per pixel. */
  strength: number;
  /** +1 if intensity rises along the normal, -1 if it falls. */
  polarity: 1 | -1;
}

export interface EdgeOptions {
  /** Gaussian derivative sigma in pixels (default 1.0). */
  sigmaG?: number;
  /** Minimum peak gradient (intensity/px) to accept. Default 2. */
  minStrength?: number;
}

/** Derivative-of-Gaussian correlation, returns d(profile)/d(px). */
function gaussianDerivative(p: Float32Array, step: number, sigmaPx: number): Float32Array {
  const s = sigmaPx / step; // sigma in samples
  const r = Math.ceil(3 * s);
  const w = new Float64Array(2 * r + 1);
  let norm = 0;
  for (let i = -r; i <= r; i++) {
    const g = Math.exp(-(i * i) / (2 * s * s));
    w[i + r] = i * g;
    norm += i * i * g;
  }
  for (let i = 0; i < w.length; i++) w[i] = (w[i] as number) / norm; // unit slope response
  const out = new Float32Array(p.length).fill(Number.NaN);
  for (let j = r; j < p.length - r; j++) {
    let acc = 0;
    let bad = false;
    for (let i = -r; i <= r; i++) {
      const v = p[j + i] as number;
      if (Number.isNaN(v)) {
        bad = true;
        break;
      }
      acc += v * (w[i + r] as number);
    }
    if (!bad) out[j] = acc / step;
  }
  return out;
}

export function locateEdge(profile: Profile, opts: EdgeOptions = {}): EdgeResult | null {
  const sigmaG = opts.sigmaG ?? 1.0;
  const minStrength = opts.minStrength ?? 2;
  const g = gaussianDerivative(profile.values, profile.step, sigmaG);
  let m = -1;
  let best = 0;
  for (let k = 1; k < g.length - 1; k++) {
    const a = Math.abs(g[k] as number);
    if (Number.isFinite(a) && a > best) {
      best = a;
      m = k;
    }
  }
  if (m < 1 || best < minStrength) return null;
  const am = Math.abs(g[m - 1] as number);
  const a0 = best;
  const ap = Math.abs(g[m + 1] as number);
  if (!Number.isFinite(am) || !Number.isFinite(ap)) return null; // peak at the valid-region boundary
  const denom = am - 2 * a0 + ap;
  // parabola vertex offset in samples: 0.5 * (am - ap) / (am - 2 a0 + ap), valid only at a maximum
  const vertex = denom < 0 ? Math.max(-0.5, Math.min(0.5, (0.5 * (am - ap)) / denom)) : 0;
  return {
    offsetPx: (m + vertex - profile.half) * profile.step,
    strength: best,
    polarity: (g[m] as number) >= 0 ? 1 : -1,
  };
}

export interface LineFit {
  /** y = a + b * x */
  a: number;
  b: number;
  rmsResidual: number;
  inliers: number;
}

/** Huber-IRLS line fit of edge points. Robust to a few bad profiles. */
export function fitLineRobust(xs: readonly number[], ys: readonly number[], iters = 20): LineFit | null {
  const n = xs.length;
  if (n < 3 || n !== ys.length) return null;
  const w = new Float64Array(n).fill(1);
  let a = 0;
  let b = 0;
  for (let it = 0; it < iters; it++) {
    let sw = 0;
    let sx = 0;
    let sy = 0;
    let sxx = 0;
    let sxy = 0;
    for (let i = 0; i < n; i++) {
      const wi = w[i] as number;
      const x = xs[i] as number;
      const y = ys[i] as number;
      sw += wi;
      sx += wi * x;
      sy += wi * y;
      sxx += wi * x * x;
      sxy += wi * x * y;
    }
    const det = sw * sxx - sx * sx;
    if (Math.abs(det) < 1e-12) return null;
    b = (sw * sxy - sx * sy) / det;
    a = (sy - b * sx) / sw;
    const res = xs.map((x, i) => (ys[i] as number) - (a + b * x));
    const absRes = res.map(Math.abs).sort((p, q) => p - q);
    const scale = Math.max(1e-9, 1.4826 * (absRes[absRes.length >> 1] as number));
    const k = 1.345 * scale;
    for (let i = 0; i < n; i++) {
      const r = Math.abs(res[i] as number);
      w[i] = r <= k ? 1 : k / r;
    }
  }
  let ss = 0;
  let inl = 0;
  const res = xs.map((x, i) => (ys[i] as number) - (a + b * x));
  const scale = Math.max(1e-9, 1.4826 * [...res.map(Math.abs)].sort((p, q) => p - q)[res.length >> 1]!);
  for (const r of res) {
    ss += r * r;
    if (Math.abs(r) <= 2.5 * scale) inl++;
  }
  return { a, b, rmsResidual: Math.sqrt(ss / n), inliers: inl };
}
