/** Digital-twin assembly with provenance (spec item 23). Visual certainty never exceeds evidence. */
import type { Epistemic, Quantity } from './epistemic.js';

export interface TwinEntry { id: string; q: Quantity<number | number[]> }
export interface TwinState {
  schema: 'lumina.twin/1';
  session: string;
  observed: TwinEntry[]; measured: TwinEntry[]; inferred: TwinEntry[]; assumed: TwinEntry[];
  unknown: { id: string; reason: string }[];
  warnings: string[];
}

export class TwinBuilder {
  private s: TwinState;
  private ids = new Set<string>();
  constructor(session: string) {
    this.s = { schema: 'lumina.twin/1', session, observed: [], measured: [], inferred: [], assumed: [], unknown: [], warnings: [] };
  }
  add(id: string, q: Quantity<number | number[]>): this {
    if (this.ids.has(id)) throw new Error(`duplicate twin id ${id}`);
    this.ids.add(id);
    if (q.status === 'UNKNOWN' || q.value === null) {
      this.s.unknown.push({ id, reason: q.refusal ?? q.note ?? 'unknown' });
      return this;
    }
    if (q.unit === 'mm' && q.scaleStatus === 'METRIC_ASSUMED') this.s.warnings.push(`${id}: millimetres rest on an assumed scale`);
    if (q.sigma === undefined && q.status === 'MEASURED') this.s.warnings.push(`${id}: measured value without defensible uncertainty`);
    const bucket: Record<Exclude<Epistemic, 'UNKNOWN'>, TwinEntry[]> = {
      OBSERVED: this.s.observed, MEASURED: this.s.measured, INFERRED: this.s.inferred, ASSUMED: this.s.assumed,
    };
    bucket[q.status as Exclude<Epistemic, 'UNKNOWN'>].push({ id, q });
    return this;
  }
  build(): TwinState { return JSON.parse(JSON.stringify(this.s)) as TwinState; }
}

/** Plain-text report line that always states class, unit, uncertainty basis. */
export function describe(id: string, q: Quantity<number | number[]>): string {
  if (q.value === null) return `${id}: UNKNOWN (${q.refusal ?? 'no value'})`;
  const v = Array.isArray(q.value) ? `[${q.value.map((x) => x.toFixed(2)).join(', ')}]` : q.value.toFixed(2);
  const sig = q.sigma !== undefined ? ` ± ${q.sigma.toFixed(2)} (${q.sigmaBasis})` : ' (relative estimate only)';
  const sc = q.unit === 'mm' ? ` [${q.scaleStatus}]` : '';
  return `${id}: ${v} ${q.unit}${sig} ${q.status}${sc}`;
}
