import type { NetRunner, RgbaImage } from '@core/perception/pipeline';
import type { KeyValueStore } from '@core/vault';
import { loadModels, type LoadedModels } from './runtime/models';
import { createNetRunner } from './runtime/ort';
import { createWorkerNetRunner } from './runtime/netProtocol';
import { openCamera, stopCamera, listCameras } from './runtime/camera';
import { createFaceTracker, type FaceTracker } from './runtime/faceTracker';
import { loadDemoImages } from './runtime/demo';
import { createIdbStore } from './runtime/idbStore';

/** Everything with side effects sits behind this interface so the UI can be tested without a camera, model or IndexedDB. */
export interface Services {
  loadModels(): Promise<LoadedModels>;
  createNet(model: ArrayBuffer): Promise<NetRunner>;
  openCamera: typeof openCamera; stopCamera: typeof stopCamera; listCameras: typeof listCameras;
  createFaceTracker(task: ArrayBuffer): Promise<FaceTracker>;
  loadDemoImages(): Promise<RgbaImage[]>;
  vaultStore(): KeyValueStore;
}
/** Prefer a Web Worker (UI stays responsive); fall back to the main thread if workers or the worker bundle are unavailable. */
async function createNet(model: ArrayBuffer): Promise<NetRunner> {
  if (typeof Worker !== 'undefined') {
    try { const w = new Worker(new URL('./runtime/netWorker.ts', import.meta.url), { type: 'module' }); return await createWorkerNetRunner(w as never, model.slice(0)); } catch { /* fall through to main thread */ }
  }
  return createNetRunner(model);
}
export const defaultServices: Services = {
  loadModels: () => loadModels(), createNet, openCamera, stopCamera, listCameras,
  createFaceTracker, loadDemoImages: () => loadDemoImages(), vaultStore: () => createIdbStore(),
};
