import { Component, useEffect, useMemo, useState, type ReactNode } from 'react';
import { estimateScale, type ScaleEstimate, type ScaleHypothesis } from '@core/scale';
import type { SessionInput } from '@core/report';
import { ModelError, type LoadedModels } from './runtime/models';
import { defaultServices, type Services } from './services';
import { Banner, Chip, DISCLAIMER, APP_VERSION } from './ui/common';
import { Live, type Finished } from './ui/Live';
import { Review, ReportView, VaultPanel } from './ui/ReviewReport';
import { ScaleWizard } from './ui/ScaleWizard';
import { Correct } from './ui/Correct';
import { Calibrate, loadIntrinsics, type StoredIntrinsics } from './ui/Calibrate';

type Phase = 'boot' | 'calibrate' | 'setup' | 'consent' | 'live' | 'review' | 'scale' | 'correct' | 'report' | 'vault';
interface Env { secure: boolean; camera: boolean; wasm: boolean; idb: boolean; isolated: boolean }
const readEnv = (): Env => ({ secure: typeof window !== 'undefined' && window.isSecureContext, camera: !!navigator.mediaDevices?.getUserMedia, wasm: typeof WebAssembly === 'object', idb: typeof indexedDB !== 'undefined', isolated: typeof crossOriginIsolated !== 'undefined' && crossOriginIsolated });

export class ErrorBoundary extends Component<{ children: ReactNode }, { err: Error | null }> {
  state = { err: null as Error | null };
  static getDerivedStateFromError(err: Error) { return { err }; }
  render() { return this.state.err ? <Banner tone="bad" role="alert">Something went wrong: {this.state.err.message}. Reload the page; no data was sent anywhere.</Banner> : this.props.children; }
}

export default function App({ services = defaultServices }: { services?: Services }) {
  const [phase, setPhase] = useState<Phase>('boot'), [models, setModels] = useState<LoadedModels | null>(null), [bootErr, setBootErr] = useState<string | null>(null);
  const [mode, setMode] = useState<'camera' | 'demo'>('demo'), [agreed, setAgreed] = useState(false), [cams, setCams] = useState<{ id: string; label: string }[]>([]), [deviceId, setDeviceId] = useState<string | undefined>();
  const [fin, setFin] = useState<Finished | null>(null), [hyps, setHyps] = useState<ScaleHypothesis[]>([]), [scale, setScale] = useState<ScaleEstimate>(() => estimateScale([]));
  const [label, setLabel] = useState('Session'), [saved, setSaved] = useState<SessionInput | null>(null), [vaultFrom, setVaultFrom] = useState<Phase>('review');
  const env = useMemo(readEnv, []);
  const [intr, setIntr] = useState<StoredIntrinsics | null>(() => loadIntrinsics()), [useInt8, setUseInt8] = useState(false);

  useEffect(() => {
    let off = false;
    services.loadModels().then((m) => { if (!off) { setModels(m); setPhase('setup'); } }).catch((e) => { if (!off) { setBootErr(e instanceof ModelError ? `${e.message}` : `Could not load models: ${(e as Error).message}`); setPhase('setup'); } });
    return () => { off = true; };
  }, [services]);
  useEffect(() => { if (phase === 'setup' && env.camera) services.listCameras().then(setCams).catch(() => undefined); }, [phase, env.camera, services]);

  const results = useMemo(() => (fin ? fin.engine.finalize(scale) : {}), [fin, scale]);
  const input = useMemo<SessionInput | null>(() => fin && models ? ({
    id: saved?.id ?? `S-${Date.now().toString(36)}`, createdAtIso: saved?.createdAtIso ?? new Date().toISOString(), label: fin.synthetic ? 'SYNTHETIC DEMO' : label, appVersion: APP_VERSION,
    device: { ...(fin.camera ? { camera: fin.camera } : {}), ...(fin.resolution ? { resolution: fin.resolution } : {}) }, models: models.versions,
    scale: { status: scale.status, mmPerPx: scale.mmPerPx, sigmaU: scale.sigmaU, warnings: scale.warnings }, frames: { accepted: fin.engine.accepted, rejected: fin.engine.rejected }, results,
    ...(intr && fin.resolution === `${intr.width}x${intr.height}` ? { intrinsics: { status: intr.relSigmaF <= 0.1 ? 'MEASURED' as const : 'ASSUMED' as const, source: `checkerboard calibration ${intr.savedAtIso.slice(0, 10)}`, fx: intr.fx, relSigmaF: intr.relSigmaF, rmsPx: intr.rmsPx } } : {}),
  }) : null, [fin, models, scale, results, label, saved, intr]);

  const faceOk = !!models?.faceTask;
  const reset = () => { setFin(null); setHyps([]); setScale(estimateScale([])); setSaved(null); setPhase('setup'); };

  return (
    <ErrorBoundary>
      <header className="top"><h1>Lumina Smile Lab</h1><span className="ver">v{APP_VERSION}</span><button className="ghost" onClick={() => { setVaultFrom(phase); setPhase('vault'); }}>Vault</button></header>
      <main>
        {phase === 'boot' && <p role="status">Verifying and loading models…</p>}
        {phase === 'setup' && (
          <section aria-label="Setup">
            <Banner>{DISCLAIMER}</Banner>
            {bootErr && <Banner tone="bad" role="alert">{bootErr}</Banner>}
            <h2>System check</h2>
            <ul className="checks">
              <li><Chip kind={models ? 'OK' : 'BAD'}>{models ? 'OK' : 'FAIL'}</Chip> Dental network and gate installed and integrity-verified (SHA-256)</li>
              <li><Chip kind={faceOk ? 'OK' : 'WARN'}>{faceOk ? 'OK' : 'MISSING'}</Chip> Face model {faceOk ? 'installed' : 'not installed: run "npm run model:install -- <path>" (camera mode needs it; the demo does not)'}</li>
              <li><Chip kind={env.secure ? 'OK' : 'WARN'}>{env.secure ? 'OK' : 'NO'}</Chip> Secure context (HTTPS or localhost)</li>
              <li><Chip kind={env.camera ? 'OK' : 'WARN'}>{env.camera ? 'OK' : 'NO'}</Chip> Camera API</li>
              <li><Chip kind={env.wasm ? 'OK' : 'BAD'}>{env.wasm ? 'OK' : 'NO'}</Chip> WebAssembly</li>
              <li><Chip kind={env.idb ? 'OK' : 'WARN'}>{env.idb ? 'OK' : 'NO'}</Chip> Local storage for the encrypted vault</li>
              <li><Chip kind={env.isolated ? 'OK' : 'WARN'}>{env.isolated ? 'OK' : 'single-thread'}</Chip> Cross-origin isolation (multi-threaded inference)</li>
            </ul>
            {cams.length > 1 && <label>Camera <select value={deviceId ?? ''} onChange={(e) => setDeviceId(e.target.value || undefined)}><option value="">Default</option>{cams.map((c) => <option key={c.id} value={c.id}>{c.label}</option>)}</select></label>}
            {models?.dentalNetInt8 && <label><input type="checkbox" checked={useInt8} onChange={(e) => setUseInt8(e.target.checked)} /> Use the compact INT8 network (3.7x smaller, ~30% faster; equal accuracy on the synthetic test set)</label>}
            <label>Session label (use a pseudonym, not a name) <input value={label} onChange={(e) => setLabel(e.target.value)} maxLength={60} /></label>
            <div className="row">
              <button disabled={!models || !faceOk || !env.camera || !env.secure} onClick={() => { setMode('camera'); setPhase('consent'); }}>Start camera session</button>
              <button className="secondary" disabled={!models} onClick={() => { setMode('demo'); setPhase('consent'); }}>Run synthetic demo</button>
              <button className="ghost" disabled={!env.camera || !env.secure} onClick={() => setPhase('calibrate')}>Calibrate camera (optional){intr ? ` · saved ${intr.width}x${intr.height}` : ''}</button>
            </div>
          </section>
        )}
        {phase === 'calibrate' && <Calibrate services={services} {...(deviceId ? { deviceId } : {})} onSaved={(i) => { setIntr(i); setPhase('setup'); }} onClose={() => setPhase('setup')} />}
        {phase === 'consent' && (
          <section aria-label="Consent">
            <h2>Before you start</h2>
            <ul><li>All processing happens on this device. Video and results are not uploaded.</li><li>Saved sessions are encrypted with your passphrase.</li><li>{DISCLAIMER}</li></ul>
            <label><input type="checkbox" checked={agreed} onChange={(e) => setAgreed(e.target.checked)} /> I understand this is a research prototype and will not use it for clinical decisions.{mode === 'camera' && ' The person on camera has agreed to be recorded for this analysis.'}</label>
            <div className="row"><button disabled={!agreed} onClick={() => setPhase('live')}>Continue</button><button className="ghost" onClick={() => setPhase('setup')}>Back</button></div>
          </section>
        )}
        {phase === 'live' && models && <Live mode={mode} models={useInt8 && models.dentalNetInt8 ? { ...models, dentalNet: models.dentalNetInt8, versions: { ...models.versions, dentalNet: `${models.versions.dentalNet}+int8` } } : models} services={services} {...(deviceId ? { deviceId } : {})} onFinished={(f) => { setFin(f); setPhase('review'); }} onCancel={() => setPhase('setup')} />}
        {phase === 'review' && fin && input && (
          <Review results={results} scale={scale} synthetic={fin.synthetic} frames={input.frames} canScale={!!fin.engine.best} canCorrect={!!fin.engine.best}
            onScale={() => setPhase('scale')} onCorrect={() => setPhase('correct')} onReport={() => setPhase('report')} onSave={() => { setVaultFrom('review'); setPhase('vault'); }} onNew={reset} />
        )}
        {phase === 'scale' && fin?.engine.best && <ScaleWizard snapshot={fin.engine.best.snapshot} initial={hyps} ipdPx={fin.engine.ipdPx} onApply={(h, e) => { setHyps(h); setScale(e); setPhase('review'); }} onClose={() => setPhase('review')} />}
        {phase === 'correct' && fin?.engine.best && <Correct best={fin.engine.best} scale={scale} camera={fin.camera ?? 'unknown'} onClose={() => setPhase('review')} />}
        {phase === 'report' && input && <ReportView input={input} onClose={() => setPhase('review')} onSave={() => { setVaultFrom('report'); setPhase('vault'); }} />}
        {phase === 'vault' && <VaultPanel store={services.vaultStore()} current={input} onOpen={(s) => { setSaved(s); setFin(null); setPhase('setup'); }} onClose={() => setPhase(fin ? vaultFrom : 'setup')} />}
        {phase === 'vault' && saved && !fin && <ReportView input={saved} onClose={() => setSaved(null)} />}
      </main>
      <footer>{DISCLAIMER}</footer>
    </ErrorBoundary>
  );
}
