/**
 * Face geometry from 478 MediaPipe-style landmarks (normalised x,y; z on roughly the same scale as x).
 * All outputs are INFERRED: the landmarks are a generic face model's regression, not dental measurements.
 */
import type { Point } from './perception/pipeline.js';

export interface Landmark { x: number; y: number; z: number }
/** Inner lip contour (opening polygon), in MediaPipe FaceMesh numbering. */
export const INNER_LIP = [78, 95, 88, 178, 87, 14, 317, 402, 318, 324, 308, 415, 310, 311, 312, 13, 82, 81, 80, 191] as const;
export const EYE_OUTER = { right: 33, left: 263 } as const;   // subject's right/left
export const MIDLINE_RIGID = [10, 151, 9, 8, 168, 6, 197, 195, 5, 4, 1] as const;

export function toPx(lm: Landmark[], w: number, h: number, i: number): Point & { z: number } {
  const p = lm[i];
  if (!p) throw new RangeError(`landmark ${i} missing (have ${lm.length})`);
  return { x: p.x * w, y: p.y * h, z: p.z * w };
}

export function innerLipPolygon(lm: Landmark[], w: number, h: number): Point[] {
  return INNER_LIP.map((i) => { const p = toPx(lm, w, h, i); return { x: p.x, y: p.y }; });
}

export interface FaceGeometry {
  /** x of the facial midline (line through rigid forehead/nose landmarks) at image row y. */
  midlineXAt(y: number): number;
  /** Angle of the eye line in image coordinates (deg, + = clockwise on screen since y points down). */
  eyeLineDeg: number;
  /** Subject-left yaw positive (deg), pitch positive = looking down, roll as eye-line angle. */
  pose: { yawDeg: number; pitchDeg: number; rollDeg: number };
  mouthWidthPx: number;
  interocularPx: number;
}

/** Total-least-squares line through the rigid midline landmarks. Returns point + unit direction. */
export function fitMidline(lm: Landmark[], w: number, h: number): { cx: number; cy: number; dx: number; dy: number; rms: number } {
  const pts = MIDLINE_RIGID.map((i) => toPx(lm, w, h, i));
  const cx = pts.reduce((a, p) => a + p.x, 0) / pts.length, cy = pts.reduce((a, p) => a + p.y, 0) / pts.length;
  let sxx = 0, sxy = 0, syy = 0;
  for (const p of pts) { sxx += (p.x - cx) ** 2; sxy += (p.x - cx) * (p.y - cy); syy += (p.y - cy) ** 2; }
  const th = 0.5 * Math.atan2(2 * sxy, sxx - syy);
  let dx = Math.cos(th), dy = Math.sin(th);
  if (dy < 0) { dx = -dx; dy = -dy; } // point downward
  let ss = 0;
  for (const p of pts) ss += ((p.x - cx) * dy - (p.y - cy) * dx) ** 2;
  return { cx, cy, dx, dy, rms: Math.sqrt(ss / pts.length) };
}

export function faceGeometry(lm: Landmark[], w: number, h: number): FaceGeometry {
  const ml = fitMidline(lm, w, h);
  const r = toPx(lm, w, h, EYE_OUTER.right), l = toPx(lm, w, h, EYE_OUTER.left);
  const eyeLineDeg = (Math.atan2(l.y - r.y, l.x - r.x) * 180) / Math.PI;
  const yawDeg = (Math.atan2(l.z - r.z, l.x - r.x) * 180) / Math.PI;   // subject-left positive
  const top = toPx(lm, w, h, 10), chin = toPx(lm, w, h, 152);
  const pitchDeg = (Math.atan2(chin.z - top.z, chin.y - top.y) * 180) / Math.PI;
  const m0 = toPx(lm, w, h, 61), m1 = toPx(lm, w, h, 291);
  return {
    midlineXAt: (y) => (Math.abs(ml.dy) < 1e-9 ? ml.cx : ml.cx + ((y - ml.cy) / ml.dy) * ml.dx),
    eyeLineDeg, pose: { yawDeg, pitchDeg, rollDeg: eyeLineDeg },
    mouthWidthPx: Math.hypot(m1.x - m0.x, m1.y - m0.y), interocularPx: Math.hypot(l.x - r.x, l.y - r.y),
  };
}

/** Smile score in [0,1] from MediaPipe blendshape categories if present; undefined otherwise. */
export function smileFromBlendshapes(b: Record<string, number> | undefined): number | undefined {
  if (!b) return undefined;
  const a = b['mouthSmileLeft'], c = b['mouthSmileRight'];
  return a === undefined || c === undefined ? undefined : Math.min(1, Math.max(0, (a + c) / 2));
}
