import type { KeyValueStore } from '@core/vault';
/** IndexedDB-backed KeyValueStore. Values are already encrypted by Vault before they reach this layer. */
export function createIdbStore(dbName = 'lumina-vault', storeName = 'sessions'): KeyValueStore {
  const open = (): Promise<IDBDatabase> => new Promise((res, rej) => {
    const r = indexedDB.open(dbName, 1);
    r.onupgradeneeded = () => r.result.createObjectStore(storeName);
    r.onsuccess = () => res(r.result); r.onerror = () => rej(r.error ?? new Error('IndexedDB unavailable'));
  });
  const tx = async <T,>(mode: IDBTransactionMode, f: (s: IDBObjectStore) => IDBRequest<T>): Promise<T> => {
    const db = await open();
    return new Promise<T>((res, rej) => { const t = db.transaction(storeName, mode); const rq = f(t.objectStore(storeName)); t.oncomplete = () => { db.close(); res(rq.result); }; t.onerror = () => { db.close(); rej(t.error); }; });
  };
  return {
    get: async (k) => ((await tx('readonly', (s) => s.get(k))) as string | undefined) ?? null,
    set: async (k, v) => { await tx('readwrite', (s) => s.put(v, k)); },
    delete: async (k) => { await tx('readwrite', (s) => s.delete(k)); },
    keys: async () => (await tx('readonly', (s) => s.getAllKeys())).map(String),
  };
}
