import type { ReactNode } from 'react';
import type { LiveUpdate } from '../runtime/engine';
import type { Epistemic } from '@core/epistemic';

export const APP_VERSION = '0.1.0';
export function Chip({ kind, children }: { kind: Epistemic | 'OK' | 'WARN' | 'BAD'; children: ReactNode }) { return <span className={`chip chip-${kind}`}>{children}</span>; }
export function Banner({ tone = 'warn', children, role }: { tone?: 'warn' | 'bad' | 'info'; children: ReactNode; role?: 'alert' | 'status' }) { return <div className={`banner banner-${tone}`} role={role}>{children}</div>; }
export const DISCLAIMER = 'Research prototype. Not validated for clinical decisions. Values are estimates from a webcam image and a neural network trained on synthetic data; uncertainties describe repeatability, not accuracy.';

export const PROMPT_TEXT: Record<string, string> = {
  HOLD_STILL: 'Hold still', INCREASE_LIGHT: 'More light needed', REDUCE_GLARE: 'Reduce glare or bright reflections', MOVE_CLOSER: 'Move closer to the camera',
  TEETH_NOT_VISIBLE: 'Show your teeth', FOCUS_UNSTABLE: 'Image is blurry: wait for focus or clean the lens', LEVEL_HEAD: 'Level your head (look straight ahead)', OK: 'Good, keep going',
  NO_FACE: 'No face detected: centre your face in the frame', FEW_TEETH_VISIBLE: 'Not enough teeth visible', FEW_TOOTH_PIXELS: 'Not enough teeth visible',
};
export function promptFor(u: LiveUpdate | null): string {
  if (!u) return 'Starting…';
  if (u.kind === 'NO_FACE') return PROMPT_TEXT['NO_FACE'] as string;
  if (u.kind === 'DONE') return 'Capture complete';
  const c = u.capture;
  if (c?.prompt === 'STEP_HINT') return c.hint ?? '';
  if (c && c.prompt !== 'OK') return PROMPT_TEXT[c.prompt] ?? c.prompt;
  if (u.analysis?.refusal) return PROMPT_TEXT[u.analysis.flags[0] ?? ''] ?? 'Not enough visual evidence';
  return PROMPT_TEXT['OK'] as string;
}
export const STEP_LABEL: Record<string, string> = { CENTER: 'Look straight, mouth relaxed', LEFT: 'Turn slightly to your left', RIGHT: 'Turn slightly to your right', SMILE: 'Smile fully (measurements are taken here)', TILT: 'Tilt your head slightly', CLOSEUP: 'Move closer' };
export const STEPS = ['CENTER', 'LEFT', 'RIGHT', 'SMILE', 'TILT'] as const;

const KIND_COLOR: Record<string, string> = { incisal_mid: '#22d3ee', zenith: '#f472b6', mesial_corner: '#a3e635', distal_corner: '#facc15', papilla: '#fb923c', dental_midline: '#ffffff' };
/** Draw accepted keypoints (filled) and gated-out ones (hollow grey) in source-frame coordinates scaled to the canvas. */
export function drawOverlay(canvas: HTMLCanvasElement, u: LiveUpdate | null, frameW: number, frameH: number): void {
  const ctx = canvas.getContext('2d'); if (!ctx) return;
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  if (!u?.analysis || !u.offset) return;
  const sx = canvas.width / frameW, sy = canvas.height / frameH, { ox, oy } = u.offset;
  const b = u.analysis.box;
  ctx.strokeStyle = 'rgba(148,163,184,.7)'; ctx.setLineDash([6, 4]); ctx.lineWidth = 1;
  ctx.strokeRect((b.x0) * sx, (b.y0) * sy, b.w * sx, b.h * sy); ctx.setLineDash([]);
  const r = Math.max(2.5, canvas.width / 220);
  for (const k of u.analysis.keypoints) {
    if (k.state === 'ACCEPTED' && k.xy.value) {
      ctx.fillStyle = KIND_COLOR[k.kind] ?? '#fff'; ctx.beginPath(); ctx.arc((k.xy.value[0] + ox) * sx, (k.xy.value[1] + oy) * sy, r, 0, 6.283); ctx.fill();
    } else if (k.state === 'GATED_OUT' && k.roiXY) {
      const x = (u.analysis.tf.scale * k.roiXY[0] + u.analysis.tf.ox + ox) * sx, y = (u.analysis.tf.scale * k.roiXY[1] + u.analysis.tf.oy + oy) * sy;
      ctx.strokeStyle = 'rgba(148,163,184,.8)'; ctx.beginPath(); ctx.arc(x, y, r, 0, 6.283); ctx.stroke();
    }
  }
}
export function download(name: string, text: string, mime: string): void {
  const url = URL.createObjectURL(new Blob([text], { type: mime }));
  const a = document.createElement('a'); a.href = url; a.download = name; document.body.appendChild(a); a.click(); a.remove(); setTimeout(() => URL.revokeObjectURL(url), 1000);
}
