/**
 * Camera calibration from a planar checkerboard (Zhang 2000): homographies by normalised DLT, closed-form intrinsics,
 * then Levenberg-Marquardt refinement of fx, fy, cx, cy, k1, k2 and all view poses. Provides a parameter covariance.
 * Intrinsics from here are the only ones the system may label MEASURED (see calibration.classifyIntrinsics).
 */
import { AtA, invert, jacobiEigen, solveLinear } from './linalg.js';
import { type GrayImage } from './subpixel.js';
import { rodrigues, type Vec3 } from './pose.js';

export type P2 = [number, number];
export function homographyDLT(src: P2[], dst: P2[]): number[][] {
  if (src.length < 4 || src.length !== dst.length) throw new RangeError('need >= 4 correspondences');
  const norm = (pts: P2[]) => {
    const n = pts.length, cx = pts.reduce((s, p) => s + p[0], 0) / n, cy = pts.reduce((s, p) => s + p[1], 0) / n;
    const d = pts.reduce((s, p) => s + Math.hypot(p[0] - cx, p[1] - cy), 0) / n, s = Math.SQRT2 / (d || 1);
    return { T: [[s, 0, -s * cx], [0, s, -s * cy], [0, 0, 1]], p: pts.map((p) => [s * (p[0] - cx), s * (p[1] - cy)] as P2) };
  };
  const a = norm(src), b = norm(dst), rows: number[][] = [];
  for (let i = 0; i < src.length; i++) {
    const [x, y] = a.p[i] as P2, [u, v] = b.p[i] as P2;
    rows.push([-x, -y, -1, 0, 0, 0, u * x, u * y, u], [0, 0, 0, -x, -y, -1, v * x, v * y, v]);
  }
  const h = jacobiEigen(AtA(rows)).vectors[0] as number[];
  const Hn = [[h[0], h[1], h[2]], [h[3], h[4], h[5]], [h[6], h[7], h[8]]] as number[][];
  const Tb = invert(b.T) as number[][];
  const mul = (A: number[][], B: number[][]) => A.map((r) => B[0]!.map((_, j) => r.reduce((s, v, k) => s + v * (B[k]![j] as number), 0)));
  const H = mul(mul(Tb, Hn), a.T), s = H[2]![2] as number;
  return H.map((r) => r.map((v) => v / s));
}
export const applyH = (H: number[][], p: P2): P2 => { const w = (H[2]![0] as number) * p[0] + (H[2]![1] as number) * p[1] + (H[2]![2] as number); return [((H[0]![0] as number) * p[0] + (H[0]![1] as number) * p[1] + (H[0]![2] as number)) / w, ((H[1]![0] as number) * p[0] + (H[1]![1] as number) * p[1] + (H[1]![2] as number)) / w]; };

export interface Intrinsics6 { fx: number; fy: number; cx: number; cy: number; k1: number; k2: number }
export interface View { rvec: Vec3; t: Vec3 }
export interface ZhangResult { K: Intrinsics6; views: View[]; rmsPx: number; perViewRms: number[]; cov: number[][]; sigma: { fx: number; fy: number; cx: number; cy: number; k1: number; k2: number }; relSigmaF: number }

function vij(H: number[][], i: number, j: number): number[] {
  const h = (r: number, c: number) => H[r]![c] as number;
  return [h(0, i) * h(0, j), h(0, i) * h(1, j) + h(1, i) * h(0, j), h(1, i) * h(1, j), h(2, i) * h(0, j) + h(0, i) * h(2, j), h(2, i) * h(1, j) + h(1, i) * h(2, j), h(2, i) * h(2, j)];
}
function closedForm(Hs: number[][][]): { fx: number; fy: number; cx: number; cy: number } {
  const V: number[][] = [];
  for (const H of Hs) { const a = vij(H, 0, 1), b = vij(H, 0, 0), c = vij(H, 1, 1); V.push(a, b.map((v, k) => v - (c[k] as number))); }
  let B = jacobiEigen(AtA(V)).vectors[0] as number[];
  if ((B[0] as number) < 0) B = B.map((v) => -v);
  const [B11, B12, B22, B13, B23, B33] = B as [number, number, number, number, number, number];
  const v0 = (B12 * B13 - B11 * B23) / (B11 * B22 - B12 * B12), lam = B33 - (B13 * B13 + v0 * (B12 * B13 - B11 * B23)) / B11;
  const fx = Math.sqrt(lam / B11), fy = Math.sqrt((lam * B11) / (B11 * B22 - B12 * B12)), gamma = (-B12 * fx * fx * fy) / lam, u0 = (gamma * v0) / fy - (B13 * fx * fx) / lam;
  if (![fx, fy, u0, v0].every(Number.isFinite)) throw new Error('degenerate calibration views (vary the board orientation)');
  return { fx, fy, cx: u0, cy: v0 };
}
function poseFromH(H: number[][], K: { fx: number; fy: number; cx: number; cy: number }): View {
  const Ki = [[1 / K.fx, 0, -K.cx / K.fx], [0, 1 / K.fy, -K.cy / K.fy], [0, 0, 1]];
  const col = (j: number) => { const c = [H[0]![j], H[1]![j], H[2]![j]] as number[]; return Ki.map((r) => r[0]! * c[0]! + r[1]! * c[1]! + r[2]! * c[2]!); };
  const h1 = col(0), h2 = col(1), h3 = col(2), l = 1 / Math.hypot(...h1);
  let r1 = h1.map((v) => v * l), r2 = h2.map((v) => v * l), t = h3.map((v) => v * l);
  if ((t[2] as number) < 0) { r1 = r1.map((v) => -v); r2 = r2.map((v) => -v); t = t.map((v) => -v); }
  const r3 = [r1[1]! * r2[2]! - r1[2]! * r2[1]!, r1[2]! * r2[0]! - r1[0]! * r2[2]!, r1[0]! * r2[1]! - r1[1]! * r2[0]!];
  // nearest rotation via polar decomposition (Newton iteration)
  let R = [r1, r2, r3].map((r) => r.slice()); R = [[r1[0]!, r2[0]!, r3[0]!], [r1[1]!, r2[1]!, r3[1]!], [r1[2]!, r2[2]!, r3[2]!]];
  for (let k = 0; k < 20; k++) { const Ri = invert(R.map((r, i) => r.map((_, j) => R[j]![i] as number))) as number[][]; R = R.map((r, i) => r.map((v, j) => 0.5 * (v + (Ri[i]![j] as number)))); }
  const tr = R[0]![0]! + R[1]![1]! + R[2]![2]!, th = Math.acos(Math.max(-1, Math.min(1, (tr - 1) / 2)));
  const ax = [R[2]![1]! - R[1]![2]!, R[0]![2]! - R[2]![0]!, R[1]![0]! - R[0]![1]!], n = Math.hypot(...ax) || 1;
  return { rvec: th < 1e-9 ? [0, 0, 0] : [ax[0]! / n * th, ax[1]! / n * th, ax[2]! / n * th], t: t as Vec3 };
}
export function project(K: Intrinsics6, v: View, X: Vec3): P2 {
  const R = rodrigues(v.rvec), x = R[0][0] * X[0] + R[0][1] * X[1] + R[0][2] * X[2] + v.t[0], y = R[1][0] * X[0] + R[1][1] * X[1] + R[1][2] * X[2] + v.t[1], z = R[2][0] * X[0] + R[2][1] * X[1] + R[2][2] * X[2] + v.t[2];
  const a = x / z, b = y / z, r2 = a * a + b * b, d = 1 + K.k1 * r2 + K.k2 * r2 * r2;
  return [K.fx * a * d + K.cx, K.fy * b * d + K.cy];
}

/** board: plane points in mm (Z = 0); obs[v][i]: detected pixel for board[i] in view v. */
export function calibrateZhang(board: P2[], obs: P2[][], opt: { sigmaPx?: number; fixDistortion?: boolean } = {}): ZhangResult {
  if (obs.length < 3) throw new RangeError('need at least 3 views');
  const Hs = obs.map((o) => homographyDLT(board, o)), K0 = closedForm(Hs);
  let p: number[] = [K0.fx, K0.fy, K0.cx, K0.cy, 0, 0];
  const views = Hs.map((H) => poseFromH(H, K0)); views.forEach((v) => p.push(...v.rvec, ...v.t));
  const nv = obs.length, N = board.length, free = (opt.fixDistortion ? 4 : 6);
  const unpack = (q: number[]): { K: Intrinsics6; vs: View[] } => ({ K: { fx: q[0]!, fy: q[1]!, cx: q[2]!, cy: q[3]!, k1: q[4]!, k2: q[5]! }, vs: Array.from({ length: nv }, (_, i) => ({ rvec: [q[6 + 6 * i]!, q[7 + 6 * i]!, q[8 + 6 * i]!] as Vec3, t: [q[9 + 6 * i]!, q[10 + 6 * i]!, q[11 + 6 * i]!] as Vec3 })) });
  const resid = (q: number[]): number[] => { const { K, vs } = unpack(q), r: number[] = []; for (let v = 0; v < nv; v++) for (let i = 0; i < N; i++) { const pr = project(K, vs[v] as View, [board[i]![0], board[i]![1], 0]); r.push(pr[0] - obs[v]![i]![0], pr[1] - obs[v]![i]![1]); } return r; };
  const idx = (): number[] => [...Array(p.length).keys()].filter((k) => !(opt.fixDistortion && (k === 4 || k === 5)));
  const jac = (q: number[], r0: number[], ids: number[]) => ids.map((k) => { const h = 1e-6 * Math.max(1, Math.abs(q[k]!)), a = q.slice(); a[k] = q[k]! + h; const ra = resid(a); return ra.map((v, i) => (v - (r0[i] as number)) / h); });
  let lam = 1e-3, cost = resid(p).reduce((s, v) => s + v * v, 0);
  for (let it = 0; it < 80; it++) {
    const ids = idx(), r0 = resid(p), Jt = jac(p, r0, ids), n = ids.length;
    const A = Array.from({ length: n }, (_, a) => Array.from({ length: n }, (_, b) => Jt[a]!.reduce((s, v, i) => s + v * (Jt[b]![i] as number), 0))), g = Jt.map((c) => c.reduce((s, v, i) => s + v * (r0[i] as number), 0));
    let improved = false;
    for (let tries = 0; tries < 8; tries++) {
      const Ad = A.map((r, i) => r.map((v, j) => (i === j ? v * (1 + lam) + 1e-12 : v))), d = solveLinear(Ad, g.map((v) => -v)); if (!d) { lam *= 10; continue; }
      const q = p.slice(); ids.forEach((k, a) => { q[k] = q[k]! + (d[a] as number); });
      const c = resid(q).reduce((s, v) => s + v * v, 0);
      if (c < cost) { const rel = (cost - c) / cost; p = q; cost = c; lam = Math.max(1e-9, lam / 5); improved = true; if (rel < 1e-10) it = 999; break; } lam *= 10;
    }
    if (!improved) break;
  }
  const { K, vs } = unpack(p), r = resid(p), sig = opt.sigmaPx ?? Math.sqrt(cost / Math.max(1, r.length - p.length));
  const ids = idx(), Jt = jac(p, r, ids), n = ids.length;
  const A = Array.from({ length: n }, (_, a) => Array.from({ length: n }, (_, b) => Jt[a]!.reduce((s, v, i) => s + v * (Jt[b]![i] as number), 0)));
  const inv = invert(A.map((row, i) => row.map((v, j) => (i === j ? v + 1e-12 : v)))) ?? A.map(() => A.map(() => NaN));
  const full = (k: number) => inv[ids.indexOf(k)]?.[ids.indexOf(k)] as number | undefined;
  const sd = (k: number) => Math.sqrt(Math.max(0, (full(k) ?? 0) * sig * sig));
  const perViewRms = Array.from({ length: nv }, (_, v) => Math.sqrt(r.slice(2 * N * v, 2 * N * (v + 1)).reduce((s, x) => s + x * x, 0) / N));
  return { K, views: vs, rmsPx: Math.sqrt(cost / (r.length / 2)), perViewRms, cov: inv.slice(0, free).map((row) => row.slice(0, free).map((v) => v * sig * sig)),
    sigma: { fx: sd(0), fy: sd(1), cx: sd(2), cy: sd(3), k1: sd(4), k2: sd(5) }, relSigmaF: sd(0) / K.fx };
}

/** Saddle-point (checkerboard corner) refinement by minimising sum (grad I . (p - c))^2 over a window. */
export function refineCorner(g: GrayImage, p: P2, radius = 6, iters = 12): P2 | null {
  let [cx, cy] = p;
  const at = (x: number, y: number) => { const xc = Math.min(Math.max(x, 0), g.width - 1.001), yc = Math.min(Math.max(y, 0), g.height - 1.001), x0 = Math.floor(xc), y0 = Math.floor(yc), fx = xc - x0, fy = yc - y0; const d = g.data, w = g.width; return (d[y0 * w + x0] as number) * (1 - fx) * (1 - fy) + (d[y0 * w + x0 + 1] as number) * fx * (1 - fy) + (d[(y0 + 1) * w + x0] as number) * (1 - fx) * fy + (d[(y0 + 1) * w + x0 + 1] as number) * fx * fy; };
  for (let it = 0; it < iters; it++) {
    let a = 0, b = 0, c = 0, e = 0, f = 0;
    for (let y = Math.round(cy) - radius; y <= Math.round(cy) + radius; y++) for (let x = Math.round(cx) - radius; x <= Math.round(cx) + radius; x++) {
      const gx = (at(x + 1, y) - at(x - 1, y)) / 2, gy = (at(x, y + 1) - at(x, y - 1)) / 2, w = Math.exp(-((x - cx) ** 2 + (y - cy) ** 2) / (2 * (radius / 2) ** 2));
      const xx = w * gx * gx, xy = w * gx * gy, yy = w * gy * gy; a += xx; b += xy; c += yy; e += xx * x + xy * y; f += xy * x + yy * y;
    }
    const det = a * c - b * b; if (Math.abs(det) < 1e-6) return null;
    const nx = (c * e - b * f) / det, ny = (a * f - b * e) / det;
    if (!Number.isFinite(nx) || Math.hypot(nx - cx, ny - cy) > radius) return null;
    const moved = Math.hypot(nx - cx, ny - cy); cx = nx; cy = ny; if (moved < 1e-3) break;
  }
  return [cx, cy];
}

/** From 4 user clicks on the outer inner-corners of a cols x rows grid, predict all corners, snap them, re-fit, repeat. */
export function locateBoardCorners(g: GrayImage, clicks: [P2, P2, P2, P2], cols: number, rows: number, radius = 7): { corners: P2[]; refined: number } | null {
  const grid: P2[] = []; for (let j = 0; j < rows; j++) for (let i = 0; i < cols; i++) grid.push([i, j]);
  let H = homographyDLT([[0, 0], [cols - 1, 0], [cols - 1, rows - 1], [0, rows - 1]], clicks), pts = grid.map((q) => applyH(H, q)), refined = 0;
  for (let round = 0; round < 3; round++) {
    const snapped = pts.map((q) => refineCorner(g, q, radius)), ok = snapped.filter((s): s is P2 => s !== null); refined = ok.length;
    if (ok.length < 0.8 * grid.length) return null;
    const src: P2[] = [], dst: P2[] = []; snapped.forEach((s, i) => { if (s) { src.push(grid[i] as P2); dst.push(s); } });
    H = homographyDLT(src, dst); pts = grid.map((q, i) => snapped[i] ?? applyH(H, q));
  }
  return { corners: pts, refined };
}
