/**
 * Rigid head pose from rigid landmarks (design sections D1/D6, FrameGraph).
 *
 * Levenberg-Marquardt PnP with Huber reweighting on NORMALIZED image coordinates
 * (so the caller must undistort and divide by K first). Returns a covariance from the
 * Gauss-Newton approximation sigma^2 (J^T W J)^-1, which is a LOWER BOUND on the true
 * uncertainty: it assumes the 3D model is exact. Pose is INFERRED whenever the image
 * points came from a network and the model from a generic face.
 */
export type Vec3 = [number, number, number];
export type Mat3 = [Vec3, Vec3, Vec3];

export function rodrigues(r: Vec3): Mat3 {
  const th = Math.hypot(r[0], r[1], r[2]);
  if (th < 1e-12) return [[1, 0, 0], [0, 1, 0], [0, 0, 1]];
  const k: Vec3 = [r[0] / th, r[1] / th, r[2] / th];
  const c = Math.cos(th), s = Math.sin(th), v = 1 - c;
  return [
    [c + k[0] * k[0] * v, k[0] * k[1] * v - k[2] * s, k[0] * k[2] * v + k[1] * s],
    [k[1] * k[0] * v + k[2] * s, c + k[1] * k[1] * v, k[1] * k[2] * v - k[0] * s],
    [k[2] * k[0] * v - k[1] * s, k[2] * k[1] * v + k[0] * s, c + k[2] * k[2] * v],
  ];
}

export function rotate(R: Mat3, p: Vec3): Vec3 {
  return [R[0][0] * p[0] + R[0][1] * p[1] + R[0][2] * p[2], R[1][0] * p[0] + R[1][1] * p[1] + R[1][2] * p[2], R[2][0] * p[0] + R[2][1] * p[1] + R[2][2] * p[2]];
}

/** R = Rz(roll) Rx(pitch) Ry(yaw), radians. */
export function fromEuler(yaw: number, pitch: number, roll: number): Mat3 {
  const cy = Math.cos(yaw), sy = Math.sin(yaw), cx = Math.cos(pitch), sx = Math.sin(pitch), cz = Math.cos(roll), sz = Math.sin(roll);
  const RxRy: Mat3 = [[cy, 0, sy], [sx * sy, cx, -sx * cy], [-cx * sy, sx, cx * cy]];
  return [
    [cz * RxRy[0][0] - sz * RxRy[1][0], cz * RxRy[0][1] - sz * RxRy[1][1], cz * RxRy[0][2] - sz * RxRy[1][2]],
    [sz * RxRy[0][0] + cz * RxRy[1][0], sz * RxRy[0][1] + cz * RxRy[1][1], sz * RxRy[0][2] + cz * RxRy[1][2]],
    RxRy[2],
  ];
}

export function toEuler(R: Mat3): { yaw: number; pitch: number; roll: number } {
  return { yaw: Math.atan2(-R[2][0], R[2][2]), pitch: Math.asin(Math.max(-1, Math.min(1, R[2][1]))), roll: Math.atan2(-R[0][1], R[1][1]) };
}

export function solveLinear(A: number[][], b: number[]): number[] | null {
  const n = b.length;
  const M = A.map((r, i) => [...r, b[i] as number]);
  for (let c = 0; c < n; c++) {
    let p = c;
    for (let r = c + 1; r < n; r++) if (Math.abs((M[r] as number[])[c] as number) > Math.abs((M[p] as number[])[c] as number)) p = r;
    if (Math.abs((M[p] as number[])[c] as number) < 1e-14) return null;
    [M[c], M[p]] = [M[p] as number[], M[c] as number[]];
    for (let r = c + 1; r < n; r++) {
      const f = ((M[r] as number[])[c] as number) / ((M[c] as number[])[c] as number);
      for (let k = c; k <= n; k++) (M[r] as number[])[k] = ((M[r] as number[])[k] as number) - f * ((M[c] as number[])[k] as number);
    }
  }
  const x = new Array<number>(n).fill(0);
  for (let r = n - 1; r >= 0; r--) {
    let s = (M[r] as number[])[n] as number;
    for (let k = r + 1; k < n; k++) s -= ((M[r] as number[])[k] as number) * (x[k] as number);
    x[r] = s / (((M[r] as number[])[r]) as number);
  }
  return x;
}

export function invert(A: number[][]): number[][] | null {
  const n = A.length;
  const cols: number[][] = [];
  for (let j = 0; j < n; j++) {
    const e = new Array<number>(n).fill(0); e[j] = 1;
    const x = solveLinear(A, e);
    if (!x) return null;
    cols.push(x);
  }
  return Array.from({ length: n }, (_, i) => cols.map((c) => c[i] as number));
}

export interface PoseResult {
  rvec: Vec3; t: Vec3; R: Mat3;
  /** 6x6 covariance of [rvec, t]; rotation in rad^2, translation in model-unit^2. LOWER BOUND. */
  cov6: number[][];
  rmsNorm: number;
  iters: number;
  converged: boolean;
  inliers: number;
  flags: string[];
}

export interface PoseOptions { sigmaNorm: number; maxIters?: number; huber?: boolean; init?: { rvec: Vec3; t: Vec3 } }

function residuals(model: Vec3[], obs: [number, number][], p: number[]): number[] {
  const R = rodrigues([p[0] as number, p[1] as number, p[2] as number]);
  const out: number[] = [];
  for (let i = 0; i < model.length; i++) {
    const q = rotate(R, model[i] as Vec3);
    const X = q[0] + (p[3] as number), Y = q[1] + (p[4] as number), Z = q[2] + (p[5] as number);
    out.push(X / Z - (obs[i] as [number, number])[0], Y / Z - (obs[i] as [number, number])[1]);
  }
  return out;
}

export function solvePnP(model: Vec3[], obs: [number, number][], opt: PoseOptions): PoseResult | null {
  const n = model.length;
  if (n < 6 || obs.length !== n) return null;
  const flags: string[] = [];
  // init: identity rotation, depth from size ratio
  let p: number[];
  if (opt.init) p = [...opt.init.rvec, ...opt.init.t];
  else {
    const cm = model.reduce((a, m) => [a[0] + m[0] / n, a[1] + m[1] / n, a[2] + m[2] / n], [0, 0, 0]);
    const co = obs.reduce((a, o) => [a[0] + o[0] / n, a[1] + o[1] / n], [0, 0]);
    const rm = Math.sqrt(model.reduce((a, m) => a + (m[0] - cm[0]!) ** 2 + (m[1] - cm[1]!) ** 2, 0) / n);
    const ro = Math.sqrt(obs.reduce((a, o) => a + (o[0] - co[0]!) ** 2 + (o[1] - co[1]!) ** 2, 0) / n);
    const z = ro > 0 ? rm / ro + cm[2]! : 500;
    p = [0, 0, 0, co[0]! * z - cm[0]!, co[1]! * z - cm[1]!, z];
  }
  const w = new Array<number>(n).fill(1);
  let lambda = 1e-3, converged = false, iters = 0;
  const max = opt.maxIters ?? 60;
  const jac = (pp: number[]) => {
    const r0 = residuals(model, obs, pp);
    const J: number[][] = r0.map(() => new Array<number>(6).fill(0));
    for (let k = 0; k < 6; k++) {
      const h = k < 3 ? 1e-6 : Math.max(1e-6, Math.abs(pp[k] as number) * 1e-7);
      const a = pp.slice(), b = pp.slice(); a[k] = (pp[k] as number) + h; b[k] = (pp[k] as number) - h;
      const ra = residuals(model, obs, a), rb = residuals(model, obs, b);
      for (let i = 0; i < r0.length; i++) (J[i] as number[])[k] = ((ra[i] as number) - (rb[i] as number)) / (2 * h);
    }
    return { r0, J };
  };
  const cost = (r: number[]) => r.reduce((a, v, i) => a + (w[i >> 1] as number) * v * v, 0);
  const outerMax = opt.huber !== false ? 4 : 1;
  for (let outer = 0; outer < outerMax; outer++) {
    converged = false;
    if (opt.huber !== false && outer > 0) { // first pass is unweighted so the initial guess cannot reject everything
      const r = residuals(model, obs, p);
      const k = 2.5 * opt.sigmaNorm; // Huber threshold on the 2D residual norm (Rayleigh scale = sigma)
      const hard = outer >= 3; // Huber on passes 1-2, then hard-reject beyond 6 sigma
      const prev = w.slice();
      for (let i = 0; i < n; i++) { const e = Math.hypot(r[2 * i] as number, r[2 * i + 1] as number); w[i] = e <= k ? 1 : hard && e > 6 * opt.sigmaNorm ? 0 : k / e; }
      if (w.filter((x) => x > 0).length < Math.max(6, Math.ceil(0.5 * n))) for (let i = 0; i < n; i++) w[i] = prev[i] as number;
    }
    for (let it = 0; it < max; it++) {
      iters++;
      const { r0, J } = jac(p);
      const A = Array.from({ length: 6 }, () => new Array<number>(6).fill(0));
      const g = new Array<number>(6).fill(0);
      for (let i = 0; i < r0.length; i++) {
        const wi = w[i >> 1] as number;
        for (let a = 0; a < 6; a++) {
          g[a] = (g[a] as number) + wi * ((J[i] as number[])[a] as number) * (r0[i] as number);
          for (let b = 0; b < 6; b++) (A[a] as number[])[b] = ((A[a] as number[])[b] as number) + wi * ((J[i] as number[])[a] as number) * ((J[i] as number[])[b] as number);
        }
      }
      const c0 = cost(r0);
      let improved = false;
      for (let tries = 0; tries < 10; tries++) {
        const Ad = A.map((row, i) => row.map((v, j) => (i === j ? v * (1 + lambda) + 1e-18 : v)));
        const d = solveLinear(Ad, g.map((v) => -v));
        if (!d) { lambda *= 10; continue; }
        const pn = p.map((v, i) => v + (d[i] as number));
        if ((pn[5] as number) <= 0) { lambda *= 10; continue; }
        const c1 = cost(residuals(model, obs, pn));
        if (c1 < c0) {
          p = pn; lambda = Math.max(1e-9, lambda / 5); improved = true;
          if (Math.hypot(...d.slice(0, 3)) < 1e-10 && Math.hypot(...d.slice(3)) < 1e-9 * Math.abs(p[5] as number)) converged = true;
          break;
        }
        lambda *= 10;
      }
      if (!improved) { converged = true; break; }
      if (converged) break;
    }
  }
  const { r0, J } = jac(p);
  const JtJ = Array.from({ length: 6 }, () => new Array<number>(6).fill(0));
  for (let i = 0; i < r0.length; i++) for (let a = 0; a < 6; a++) for (let b = 0; b < 6; b++) (JtJ[a] as number[])[b] = ((JtJ[a] as number[])[b] as number) + (w[i >> 1] as number) * ((J[i] as number[])[a] as number) * ((J[i] as number[])[b] as number);
  const inv = invert(JtJ);
  if (!inv) return null;
  const cov6 = inv.map((r) => r.map((v) => v * opt.sigmaNorm * opt.sigmaNorm));
  let ss = 0; for (const v of r0) ss += v * v;
  const rmsNorm = Math.sqrt(ss / r0.length);
  if (rmsNorm > 2 * opt.sigmaNorm) flags.push('model_misfit');
  let inliers = 0;
  for (let i = 0; i < n; i++) if (Math.hypot(r0[2 * i] as number, r0[2 * i + 1] as number) <= 3 * opt.sigmaNorm) inliers++;
  if (inliers < Math.ceil(0.7 * n)) flags.push('many_outliers');
  const rvec: Vec3 = [p[0] as number, p[1] as number, p[2] as number];
  return { rvec, t: [p[3] as number, p[4] as number, p[5] as number], R: rodrigues(rvec), cov6, rmsNorm, iters, converged, inliers, flags };
}

/** Rigid transform composition: T_ac = T_ab * T_bc (point maps c -> b -> a). */
export interface Rigid { R: Mat3; t: Vec3 }
export function compose(ab: Rigid, bc: Rigid): Rigid {
  const Rt = (m: Mat3, n: Mat3): Mat3 => [0, 1, 2].map((i) => [0, 1, 2].map((j) => m[i as 0][0] * n[0][j as 0] + m[i as 0][1] * n[1][j as 0] + m[i as 0][2] * n[2][j as 0])) as Mat3;
  const tb = rotate(ab.R, bc.t);
  return { R: Rt(ab.R, bc.R), t: [tb[0] + ab.t[0], tb[1] + ab.t[1], tb[2] + ab.t[2]] };
}
export function invertRigid(a: Rigid): Rigid {
  const Rt: Mat3 = [[a.R[0][0], a.R[1][0], a.R[2][0]], [a.R[0][1], a.R[1][1], a.R[2][1]], [a.R[0][2], a.R[1][2], a.R[2][2]]];
  const t = rotate(Rt, a.t);
  return { R: Rt, t: [-t[0], -t[1], -t[2]] };
}
