import { FaceLandmarker, FilesetResolver } from '@mediapipe/tasks-vision';
import type { Landmark } from '@core/face';

export interface FaceFrame { landmarks: Landmark[]; blendshapes: Record<string, number> | undefined }
export interface FaceTracker { detect(video: HTMLVideoElement, tsMs: number): FaceFrame | null; close(): void }

/** MediaPipe Face Landmarker from a hash-verified model buffer; WASM served from our own origin. GPU delegate with CPU fallback. */
export async function createFaceTracker(task: ArrayBuffer): Promise<FaceTracker> {
  const fileset = await FilesetResolver.forVisionTasks(`${import.meta.env.BASE_URL}mediapipe/wasm`);
  const make = (delegate: 'GPU' | 'CPU') => FaceLandmarker.createFromOptions(fileset, {
    baseOptions: { modelAssetBuffer: new Uint8Array(task), delegate }, runningMode: 'VIDEO', numFaces: 1, outputFaceBlendshapes: true,
    minFaceDetectionConfidence: 0.5, minFacePresenceConfidence: 0.5, minTrackingConfidence: 0.5,
  });
  let lm: FaceLandmarker;
  try { lm = await make('GPU'); } catch { lm = await make('CPU'); }
  let lastTs = -1;
  return {
    detect(video, tsMs) {
      const ts = Math.max(tsMs, lastTs + 1); lastTs = ts; // MediaPipe requires strictly increasing timestamps
      const r = lm.detectForVideo(video, ts);
      const pts = r.faceLandmarks[0];
      if (!pts || pts.length < 468) return null;
      const bs: Record<string, number> = {};
      for (const c of r.faceBlendshapes?.[0]?.categories ?? []) bs[c.categoryName] = c.score;
      return { landmarks: pts.map((p) => ({ x: p.x, y: p.y, z: p.z })), blendshapes: Object.keys(bs).length ? bs : undefined };
    },
    close() { lm.close(); },
  };
}
