/**
 * Clinician-correction label records: the route to REAL training data. Export is refused without explicit consent,
 * and records contain only the mouth-ROI crop (no face), keypoints, visibility and scale status.
 */
import { KEYPOINT_LAYOUT } from './dental.js';
export interface LabelKeypoint { channel: number; x: number; y: number; visible: boolean; source: 'network' | 'clinician' | 'clinician_confirmed' }
export interface LabelRecordV1 {
  schema: 'lumina.label/1'; id: string; createdAtIso: string;
  consent: { trainingUse: true; version: string; subjectPseudonym: string };
  device: { camera: string; width: number; height: number };
  /** 192x128 mouth-ROI crop as base64 PNG. Never a full face image. */
  cropPngBase64: string;
  keypoints: LabelKeypoint[];
  scale: { status: 'METRIC_MEASURED' | 'METRIC_ASSUMED' | 'RELATIVE'; mmPerPx: number | null };
  annotator: { id: string; role: string };
}
export class LabelError extends Error { constructor(m: string) { super(m); this.name = 'LabelError'; } }
export function validateRecord(r: LabelRecordV1): void {
  if (r.schema !== 'lumina.label/1') throw new LabelError('unknown schema');
  if (r.consent?.trainingUse !== true) throw new LabelError('explicit training-use consent is required');
  if (!r.consent.subjectPseudonym || /\s/.test(r.consent.subjectPseudonym)) throw new LabelError('subject must be a pseudonym');
  if (r.keypoints.length !== KEYPOINT_LAYOUT.length) throw new LabelError(`expected ${KEYPOINT_LAYOUT.length} keypoints`);
  r.keypoints.forEach((k, i) => {
    if (k.channel !== i) throw new LabelError(`keypoint ${i} has channel ${k.channel}`);
    if (!Number.isFinite(k.x) || !Number.isFinite(k.y)) throw new LabelError(`keypoint ${i} not finite`);
    if (k.visible && (k.x < -2 || k.x > 194 || k.y < -2 || k.y > 130)) throw new LabelError(`visible keypoint ${i} outside the crop`);
  });
  if (!r.cropPngBase64 || r.cropPngBase64.length < 100) throw new LabelError('crop image missing');
}
export function correctionStats(r: LabelRecordV1): { network: number; clinician: number; confirmed: number } {
  const c = { network: 0, clinician: 0, confirmed: 0 };
  for (const k of r.keypoints) { if (k.source === 'network') c.network++; else if (k.source === 'clinician') c.clinician++; else c.confirmed++; }
  return c;
}
