/** Session engine: one iteration = one frame through quality gates, capture protocol, dental analysis and measurement. */
import { analyzeMouth, cropToTensor, lumaOf, polygonBox, NET_W, NET_H, type DentalAnalysis, type NetRunner, type Point, type RgbaImage } from '@core/perception/pipeline';
import { CaptureSession, assessQuality, type CaptureUpdate, type FrameQualityInput, type QualityDecision, type CaptureStep } from '@core/capture';
import { laplacianVariance, lumaStats, meanMotion } from '@core/quality';
import { measureFrame } from '@core/measure';
import { MeasureAggregator } from '@core/aggregate';
import { estimateScale, toMm, type ScaleEstimate } from '@core/scale';
import type { GateModel } from '@core/gate';
import { insufficientEvidence, type Provenance, type Quantity } from '@core/epistemic';
import { KeypointFilterBank } from '@core/keypointFilter';
import { runAudit, type AuditResult } from '@core/audit';
import { makeQuantity } from '@core/epistemic';
import { median } from '@core/stats';
import type { FrameSource } from './sources';

export interface LiveUpdate {
  kind: 'NO_FACE' | 'FRAME' | 'DONE';
  analysis?: DentalAnalysis; offset?: { ox: number; oy: number }; quality?: FrameQualityInput; decision?: QualityDecision;
  capture?: CaptureUpdate; step: CaptureStep | 'DONE' | 'ABORTED'; fps: number; analysisMs: number;
  accepted: number; rejected: Record<string, number>; audit?: AuditResult; filteredOutliers?: number;
}
const ALL_MEASURES = ['wl_ratio_11', 'wl_ratio_21', 'width_ratio_21_over_11', 'midline_deviation', 'incisal_cant_deg', 'gingival_display_ratio', 'width_11_px', 'width_21_px', 'midline_offset_px'];
const EDGE_DEPENDENT = ['incisal_cant_deg', 'wl_ratio_11', 'wl_ratio_21', 'gingival_display_ratio'];
export interface BestFrame { analysis: DentalAnalysis; img: RgbaImage; ox: number; oy: number; cropRgba: Uint8ClampedArray; snapshot: RgbaImage }
const PX_IDS = ['width_11_px', 'width_21_px', 'midline_offset_px'];

export class SessionEngine {
  private session = new CaptureSession();
  private agg = new MeasureAggregator();
  private prevRigid: Point[] | null = null;
  private frames = 0; private t0 = performance.now(); private lastFpsT = this.t0; private fps = 0; private fpsN = 0;
  accepted = 0; rejected: Record<string, number> = {};
  best: BestFrame | null = null; private bestScore = -1; private lastSnapT = 0;
  private running = false;
  private kf: KeypointFilterBank | null = null;
  private ipds: number[] = [];
  get ipdPx(): number | null { return this.ipds.length >= 10 ? median(this.ipds) : null; }

  constructor(private net: NetRunner, private gate: GateModel, private source: FrameSource, private prov: Provenance) {}

  get step() { return this.session.currentStep; }
  private reject(reason: string) { this.rejected[reason] = (this.rejected[reason] ?? 0) + 1; }

  async step_(): Promise<LiveUpdate> {
    const base = { step: this.session.currentStep, fps: this.fps, analysisMs: 0, accepted: this.accepted, rejected: this.rejected };
    if (this.session.currentStep === 'DONE' || this.session.currentStep === 'ABORTED') return { kind: 'DONE', ...base };
    const f = await this.source.next();
    if (!f) { this.reject('NO_FACE'); return { kind: 'NO_FACE', ...base }; }
    this.source.hint?.(this.session.currentStep);
    const box = polygonBox(f.polygon);
    const { img, ox, oy } = f.grab(box);
    const poly = f.polygon.map((p) => ({ x: p.x - ox, y: p.y - oy }));
    const analysis = await analyzeMouth(img, poly, this.net, this.gate, this.prov);
    // temporal filtering of accepted keypoints in a stable (source-frame) coordinate system; gate outliers
    const sc = analysis.tf.scale; this.kf ??= new KeypointFilterBank({ accel: 400 * sc * sc, r0: 0.25 * sc * sc });
    let outliers = 0, refinedBad = 0, refined = 0;
    for (const k of analysis.keypoints) {
      if (k.state !== 'ACCEPTED' || !k.xy.value) { this.kf.miss(k.channel); continue; }
      if (k.refinedBy) { refined++; if (Math.abs(k.edgeShiftPx ?? 0) > 1.5 * sc) refinedBad++; }
      const r = this.kf.update(k.channel, k.xy.value[0] + ox, k.xy.value[1] + oy, f.tMs / 1000);
      if (!r.accepted) { k.state = 'GATED_OUT'; k.xy = insufficientEvidence<[number, number]>('px', this.prov, 'rejected as a temporal outlier'); outliers++; continue; }
      k.xy = makeQuantity<[number, number]>({ value: [r.x - ox, r.y - oy], unit: 'px', status: 'INFERRED', modelScore: k.peak, provenance: this.prov, note: 'temporally filtered (constant-velocity Kalman, innovation-gated)' });
    }
    if (f.ipdPx) this.ipds.push(f.ipdPx);
    const gray = lumaOf(img);
    const xs = poly.map((p) => p.x), ys = poly.map((p) => p.y), x0 = Math.min(...xs), x1 = Math.max(...xs), y0 = Math.min(...ys), y1 = Math.max(...ys);
    const ls = lumaStats(gray, x0, y0, x1, y1);
    const slots = analysis.slotAreas.filter((a) => a >= 60).length;
    const quality: FrameQualityInput = {
      sharpness: laplacianVariance(gray, x0, y0, x1, y1), motionPx: meanMotion(this.prevRigid, f.rigid), clipFraction: ls.clipFraction, meanLuma: ls.mean,
      mouthWidthPx: x1 - x0, frameWidthPx: f.width, dentalVisibleFraction: slots / 8,
      yawDeg: -f.geometry.pose.yawDeg, pitchDeg: f.geometry.pose.pitchDeg, rollDeg: f.geometry.pose.rollDeg, smileScore: f.smile ?? slots / 8,
    };
    this.prevRigid = f.rigid;
    const decision = assessQuality(quality);
    const audit = runAudit([
      { id: 'face_stable', ok: quality.motionPx <= 1.5, essentialFor: ALL_MEASURES },
      { id: 'teeth_visible', ok: slots >= 4, essentialFor: ALL_MEASURES },
      { id: 'edge_methods_agree', ok: refined === 0 || refinedBad / refined <= 0.3, detail: `${refinedBad}/${refined} refined edges moved > 1.5 px`, essentialFor: EDGE_DEPENDENT },
      { id: 'keypoints_temporally_consistent', ok: outliers <= 3, detail: `${outliers} outliers this frame`, essentialFor: ALL_MEASURES },
    ]);
    const stepBefore = this.session.currentStep;
    const capture = this.session.push(quality);
    if (!capture.accepted) { if (!decision.accept) this.reject(decision.reasons[0] ?? 'QUALITY'); }
    else {
      this.accepted++;
      if (stepBefore === 'SMILE' && !analysis.refusal) {
        const geo = { ...f.geometry, midlineXAt: (y: number) => f.geometry.midlineXAt(y + oy) - ox };
        const m = measureFrame(analysis, geo, estimateScale([]), this.prov);
        for (const [id, q] of Object.entries(m)) this.agg.add(id, (audit.refusals[id]?.length ? insufficientEvidence(q.unit, this.prov, `blocked by audit: ${audit.refusals[id]!.join(', ')}`) : q) as Quantity);
        const score = analysis.keypoints.filter((k) => k.state === 'ACCEPTED').length;
        if (score > this.bestScore) {
          this.bestScore = score;
          const now = performance.now();
          const crop = cropToTensor(img, analysis.box), rgba = new Uint8ClampedArray(NET_W * NET_H * 4), P = NET_W * NET_H;
          for (let i = 0; i < P; i++) { rgba[i * 4] = (crop[i] as number) * 255; rgba[i * 4 + 1] = (crop[P + i] as number) * 255; rgba[i * 4 + 2] = (crop[2 * P + i] as number) * 255; rgba[i * 4 + 3] = 255; }
          const snap = now - this.lastSnapT > 1000 || !this.best ? f.snapshot() : this.best.snapshot;
          if (snap !== this.best?.snapshot) this.lastSnapT = now;
          this.best = { analysis, img, ox, oy, cropRgba: rgba, snapshot: snap };
        }
      }
    }
    if (analysis.refusal) this.reject(analysis.flags[0] ?? 'INSUFFICIENT_VISUAL_EVIDENCE');
    this.frames++; this.fpsN++;
    const t = performance.now();
    if (t - this.lastFpsT > 1000) { this.fps = (this.fpsN * 1000) / (t - this.lastFpsT); this.fpsN = 0; this.lastFpsT = t; }
    const stepNow = this.session.currentStep as string;
    return { kind: stepNow === 'DONE' ? 'DONE' : 'FRAME', analysis, offset: { ox, oy }, quality, decision, capture, step: this.session.currentStep, fps: this.fps, analysisMs: analysis.ms, accepted: this.accepted, rejected: this.rejected, audit, filteredOutliers: outliers };
  }

  async run(onUpdate: (u: LiveUpdate) => void): Promise<void> {
    this.running = true;
    while (this.running) {
      const u = await this.step_();
      onUpdate(u);
      if (u.kind === 'DONE') break;
      if (u.kind === 'NO_FACE') await new Promise((r) => setTimeout(r, 30));
    }
    this.running = false;
  }
  stop() { this.running = false; this.source.stop(); }

  /** Aggregate session values. Pixel-unit values are converted to mm only through the given scale (and refused without one). */
  finalize(scale: ScaleEstimate, minN = 15): Record<string, Quantity> {
    const agg = this.agg.finalize(this.prov, { minN });
    const out: Record<string, Quantity> = {};
    for (const [id, q] of Object.entries(agg)) if (!PX_IDS.includes(id)) out[id] = q;
    if (scale.status !== 'RELATIVE') {
      for (const [pxId, mmId] of [['width_11_px', 'width_11_mm'], ['width_21_px', 'width_21_mm'], ['midline_offset_px', 'midline_deviation_mm']] as const) {
        const q = agg[pxId]; if (q) out[mmId] = toMm(q, scale, this.prov);
      }
    }
    return out;
  }
}
