/** Passphrase-encrypted storage envelope (WebCrypto: PBKDF2-SHA256 -> AES-256-GCM). Works in browsers and Node 20+. */
export interface Envelope { v: 1; kdf: 'PBKDF2-SHA256'; iter: number; salt: string; iv: string; ct: string }
export interface KeyValueStore { get(key: string): Promise<string | null>; set(key: string, value: string): Promise<void>; delete(key: string): Promise<void>; keys(): Promise<string[]> }
export const MIN_ITERATIONS = 210_000;
const enc = new TextEncoder(), dec = new TextDecoder();
export const b64 = (u: Uint8Array): string => { let s = ''; for (const b of u) s += String.fromCharCode(b); return btoa(s); };
export const unb64 = (s: string): Uint8Array => { const bin = atob(s), u = new Uint8Array(bin.length); for (let i = 0; i < bin.length; i++) u[i] = bin.charCodeAt(i); return u; };
export class VaultError extends Error { constructor(m: string) { super(m); this.name = 'VaultError'; } }

const bs = (u: Uint8Array): BufferSource => u as unknown as BufferSource;
async function key(pass: string, salt: Uint8Array, iter: number): Promise<CryptoKey> {
  const base = await crypto.subtle.importKey('raw', bs(enc.encode(pass)), 'PBKDF2', false, ['deriveKey']);
  return crypto.subtle.deriveKey({ name: 'PBKDF2', salt: bs(salt), iterations: iter, hash: 'SHA-256' }, base, { name: 'AES-GCM', length: 256 }, false, ['encrypt', 'decrypt']);
}
export async function encryptJson(obj: unknown, passphrase: string, iter = 310_000): Promise<Envelope> {
  if (passphrase.length < 8) throw new VaultError('passphrase must be at least 8 characters');
  if (iter < MIN_ITERATIONS) throw new VaultError('too few KDF iterations');
  const salt = crypto.getRandomValues(new Uint8Array(16)), iv = crypto.getRandomValues(new Uint8Array(12));
  const ct = new Uint8Array(await crypto.subtle.encrypt({ name: 'AES-GCM', iv: bs(iv) }, await key(passphrase, salt, iter), bs(enc.encode(JSON.stringify(obj)))));
  return { v: 1, kdf: 'PBKDF2-SHA256', iter, salt: b64(salt), iv: b64(iv), ct: b64(ct) };
}
export async function decryptJson<T = unknown>(e: Envelope, passphrase: string): Promise<T> {
  if (e.v !== 1 || e.kdf !== 'PBKDF2-SHA256' || e.iter < MIN_ITERATIONS) throw new VaultError('unsupported or unsafe envelope');
  try {
    const pt = await crypto.subtle.decrypt({ name: 'AES-GCM', iv: bs(unb64(e.iv)) }, await key(passphrase, unb64(e.salt), e.iter), bs(unb64(e.ct)));
    return JSON.parse(dec.decode(pt)) as T;
  } catch { throw new VaultError('wrong passphrase or corrupted data'); }
}
export class MemoryStore implements KeyValueStore {
  private m = new Map<string, string>();
  async get(k: string) { return this.m.get(k) ?? null; } async set(k: string, v: string) { this.m.set(k, v); }
  async delete(k: string) { this.m.delete(k); } async keys() { return [...this.m.keys()]; }
}
export class Vault {
  constructor(private store: KeyValueStore, private passphrase: string, private iter = 310_000) {}
  async put(id: string, obj: unknown): Promise<void> { await this.store.set(id, JSON.stringify(await encryptJson(obj, this.passphrase, this.iter))); }
  async get<T>(id: string): Promise<T | null> { const s = await this.store.get(id); return s ? decryptJson<T>(JSON.parse(s) as Envelope, this.passphrase) : null; }
  async list(): Promise<string[]> { return this.store.keys(); }
  async remove(id: string): Promise<void> { await this.store.delete(id); }
}
