/**
 * Active capture protocol (design section D5): quality gates, guided state machine,
 * and information-gain based next-view selection.
 */
export interface FrameQualityInput {
  /** Laplacian variance on the mouth ROI (higher = sharper). */
  sharpness: number;
  /** Mean inter-frame motion of rigid landmarks, px. */
  motionPx: number;
  /** Fraction of ROI pixels clipped (saturated). */
  clipFraction: number;
  meanLuma: number; // 0..255
  mouthWidthPx: number;
  frameWidthPx: number;
  dentalVisibleFraction: number; // 0..1 of expected tooth area
  yawDeg: number; pitchDeg: number; rollDeg: number;
  smileScore?: number; // 0..1 blendshape-based, INFERRED
}

export interface QualityThresholds {
  minSharpness: number; maxMotionPx: number; maxClip: number;
  minLuma: number; maxLuma: number; minMouthPx: number; minDentalVisible: number;
  maxAbsPitch: number;
}
export const DEFAULT_THRESHOLDS: QualityThresholds = {
  minSharpness: 40, maxMotionPx: 1.5, maxClip: 0.03, minLuma: 70, maxLuma: 200,
  minMouthPx: 120, minDentalVisible: 0.5, maxAbsPitch: 12,
};

export type Prompt =
  | 'HOLD_STILL' | 'INCREASE_LIGHT' | 'REDUCE_GLARE' | 'MOVE_CLOSER' | 'TEETH_NOT_VISIBLE'
  | 'FOCUS_UNSTABLE' | 'LEVEL_HEAD' | 'OK';

export interface QualityDecision { accept: boolean; reasons: Prompt[] }

/** Hard gates. Order determines which prompt is shown first. */
export function assessQuality(q: FrameQualityInput, t: QualityThresholds = DEFAULT_THRESHOLDS): QualityDecision {
  const r: Prompt[] = [];
  if (q.motionPx > t.maxMotionPx) r.push('HOLD_STILL');
  if (q.meanLuma < t.minLuma) r.push('INCREASE_LIGHT');
  if (q.clipFraction > t.maxClip || q.meanLuma > t.maxLuma) r.push('REDUCE_GLARE');
  if (q.mouthWidthPx < t.minMouthPx) r.push('MOVE_CLOSER');
  if (q.dentalVisibleFraction < t.minDentalVisible) r.push('TEETH_NOT_VISIBLE');
  if (q.sharpness < t.minSharpness) r.push('FOCUS_UNSTABLE');
  if (Math.abs(q.pitchDeg) > t.maxAbsPitch) r.push('LEVEL_HEAD');
  return { accept: r.length === 0, reasons: r };
}

export type CaptureStep = 'CENTER' | 'LEFT' | 'RIGHT' | 'SMILE' | 'TILT' | 'CLOSEUP';
export const STEP_ORDER: CaptureStep[] = ['CENTER', 'LEFT', 'RIGHT', 'SMILE', 'TILT', 'CLOSEUP'];

interface StepSpec { inRange: (q: FrameQualityInput) => boolean; minFrames: number; hint: string }
const SPECS: Record<CaptureStep, StepSpec> = {
  CENTER: { inRange: (q) => Math.abs(q.yawDeg) <= 4 && Math.abs(q.rollDeg) <= 3, minFrames: 30, hint: 'Face the camera' },
  LEFT: { inRange: (q) => q.yawDeg <= -10 && q.yawDeg >= -22, minFrames: 20, hint: 'Turn slightly left' },
  RIGHT: { inRange: (q) => q.yawDeg >= 10 && q.yawDeg <= 22, minFrames: 20, hint: 'Turn slightly right' },
  SMILE: { inRange: (q) => Math.abs(q.yawDeg) <= 5 && (q.smileScore ?? 0) >= 0.6, minFrames: 40, hint: 'Smile fully' },
  TILT: { inRange: (q) => Math.abs(q.rollDeg) >= 4 && Math.abs(q.rollDeg) <= 9 && Math.abs(q.yawDeg) <= 5, minFrames: 20, hint: 'Tilt head slightly' },
  CLOSEUP: { inRange: (q) => q.mouthWidthPx >= 0.4 * q.frameWidthPx, minFrames: 20, hint: 'Move closer' },
};

export interface CaptureUpdate {
  step: CaptureStep | 'DONE' | 'ABORTED';
  accepted: boolean;
  prompt: Prompt | 'STEP_HINT';
  hint?: string;
  progress: number; // accepted in-range frames for the current step / needed
  /** Indices (frame counter) of accepted frames per completed step. */
  done: boolean;
}

export class CaptureSession {
  private idx = 0;
  private count = 0;
  private rejectedRun = 0;
  private frame = 0;
  readonly accepted: Record<CaptureStep, number[]> = { CENTER: [], LEFT: [], RIGHT: [], SMILE: [], TILT: [], CLOSEUP: [] };
  aborted = false;

  constructor(
    private readonly steps: CaptureStep[] = STEP_ORDER.filter((s) => s !== 'CLOSEUP'),
    private readonly thresholds: QualityThresholds = DEFAULT_THRESHOLDS,
    private readonly maxRejectRun = 300,
  ) {}

  get currentStep(): CaptureStep | 'DONE' | 'ABORTED' {
    if (this.aborted) return 'ABORTED';
    return this.idx >= this.steps.length ? 'DONE' : (this.steps[this.idx] as CaptureStep);
  }

  push(q: FrameQualityInput): CaptureUpdate {
    this.frame += 1;
    const step = this.currentStep;
    if (step === 'DONE' || step === 'ABORTED') return { step, accepted: false, prompt: 'OK', progress: 1, done: true };
    const spec = SPECS[step];
    const dec = assessQuality(q, this.thresholds);
    if (!dec.accept) {
      this.rejectedRun += 1;
      if (this.rejectedRun >= this.maxRejectRun) this.aborted = true; // refuse rather than collect junk
      return { step: this.currentStep, accepted: false, prompt: dec.reasons[0] as Prompt, progress: this.count / spec.minFrames, done: false };
    }
    this.rejectedRun = 0;
    if (!spec.inRange(q)) {
      return { step, accepted: false, prompt: 'STEP_HINT', hint: spec.hint, progress: this.count / spec.minFrames, done: false };
    }
    this.count += 1;
    this.accepted[step].push(this.frame);
    if (this.count >= spec.minFrames) { this.idx += 1; this.count = 0; }
    return { step: this.currentStep, accepted: true, prompt: 'OK', progress: this.count / spec.minFrames, done: this.currentStep === 'DONE' };
  }
}

/**
 * Expected information gain of one scalar measurement with Jacobian J (w.r.t. target
 * parameters) and noise variance R under Gaussian posterior covariance P:
 *   EIG = 0.5 * ln(1 + J^T P J / R)      [nats]
 */
export function expectedInformationGain(P: number[][], J: number[], R: number): number {
  let q = 0;
  for (let i = 0; i < J.length; i++) for (let j = 0; j < J.length; j++) q += (J[i] as number) * ((P[i] as number[])[j] as number) * (J[j] as number);
  return 0.5 * Math.log(1 + Math.max(0, q) / R);
}

export interface CandidateView { name: CaptureStep; jacobians: number[][]; noiseVar: number }

/** Sum of sequential rank-1 gains for the views' expected measurements. */
export function viewGain(P: number[][], v: CandidateView): number {
  const n = P.length;
  const Pc = P.map((r) => r.slice());
  let total = 0;
  for (const J of v.jacobians) {
    total += expectedInformationGain(Pc, J, v.noiseVar);
    // rank-1 posterior update P <- P - (P J J^T P) / (R + J^T P J)
    const PJ = J.map((_, i) => Pc[i]!.reduce((a, pij, j) => a + pij * (J[j] as number), 0));
    const s = v.noiseVar + J.reduce((a, ji, i) => a + ji * (PJ[i] as number), 0);
    for (let i = 0; i < n; i++) for (let j = 0; j < n; j++) (Pc[i] as number[])[j] = ((Pc[i] as number[])[j] as number) - ((PJ[i] as number) * (PJ[j] as number)) / s;
  }
  return total;
}

export type NextAction = { action: CaptureStep; gain: number } | { action: 'INSUFFICIENT_VISUAL_EVIDENCE'; gain: number };

/** Choose the most informative remaining view; if nothing helps, say so. */
export function chooseNextView(P: number[][], candidates: CandidateView[], epsilon = 0.05): NextAction {
  let best: { action: CaptureStep; gain: number } | null = null;
  for (const c of candidates) {
    const g = viewGain(P, c);
    if (!best || g > best.gain) best = { action: c.name, gain: g };
  }
  if (!best || best.gain < epsilon) return { action: 'INSUFFICIENT_VISUAL_EVIDENCE', gain: best?.gain ?? 0 };
  return best;
}
