/** Statistics primitives used by temporal consensus and the validation harness. */

/** Online mean/variance (Welford). */
export class Welford {
  n = 0;
  mean = 0;
  private m2 = 0;

  push(x: number): void {
    this.n += 1;
    const d = x - this.mean;
    this.mean += d / this.n;
    this.m2 += d * (x - this.mean);
  }
  /** Sample variance (n-1). NaN for n < 2. */
  get variance(): number {
    return this.n < 2 ? Number.NaN : this.m2 / (this.n - 1);
  }
  get sd(): number {
    return Math.sqrt(this.variance);
  }
}

export function mean(xs: readonly number[]): number {
  if (xs.length === 0) return Number.NaN;
  let s = 0;
  for (const x of xs) s += x;
  return s / xs.length;
}

export function sampleSd(xs: readonly number[]): number {
  const w = new Welford();
  for (const x of xs) w.push(x);
  return w.sd;
}

export function median(xs: readonly number[]): number {
  if (xs.length === 0) return Number.NaN;
  const s = [...xs].sort((a, b) => a - b);
  const m = s.length >> 1;
  return s.length % 2 ? (s[m] as number) : ((s[m - 1] as number) + (s[m] as number)) / 2;
}

/** Median absolute deviation scaled to be consistent with SD for normal data. */
export function madSigma(xs: readonly number[]): number {
  const m = median(xs);
  return 1.4826 * median(xs.map((x) => Math.abs(x - m)));
}

/** Indices of samples beyond k robust sigmas from the median. */
export function madOutliers(xs: readonly number[], k = 3): number[] {
  const m = median(xs);
  const s = madSigma(xs);
  if (!(s > 0)) return [];
  const out: number[] = [];
  xs.forEach((x, i) => {
    if (Math.abs(x - m) > k * s) out.push(i);
  });
  return out;
}

/** Lag-1 autocorrelation estimate. */
export function lag1Autocorr(xs: readonly number[]): number {
  const n = xs.length;
  if (n < 3) return 0;
  const m = mean(xs);
  let num = 0;
  let den = 0;
  for (let i = 0; i < n; i++) {
    const d = (xs[i] as number) - m;
    den += d * d;
    if (i > 0) num += d * ((xs[i - 1] as number) - m);
  }
  return den === 0 ? 0 : num / den;
}

/** Effective sample size for AR(1)-correlated frames: N (1 - rho) / (1 + rho). */
export function effectiveN(n: number, rho: number): number {
  const r = Math.min(0.999, Math.max(0, rho)); // negative correlation is not credited
  return (n * (1 - r)) / (1 + r);
}

/** Standard error of the mean that accounts for temporal correlation. */
export function correlatedSem(xs: readonly number[]): number {
  const sd = sampleSd(xs);
  const neff = effectiveN(xs.length, lag1Autocorr(xs));
  return sd / Math.sqrt(Math.max(1, neff));
}

export interface Agreement {
  n: number;
  bias: number;
  sdDiff: number;
  loaLow: number;
  loaHigh: number;
  mae: number;
  rmse: number;
  /** Pearson correlation of |difference| with the pair mean: crude proportional-bias flag. */
  proportionalBiasR: number;
}

/** Bland-Altman style agreement between estimates and a reference. */
export function agreement(estimate: readonly number[], reference: readonly number[]): Agreement {
  if (estimate.length !== reference.length || estimate.length < 2) {
    throw new RangeError('agreement needs two equal-length arrays with n >= 2');
  }
  const d = estimate.map((e, i) => e - (reference[i] as number));
  const avg = estimate.map((e, i) => (e + (reference[i] as number)) / 2);
  const bias = mean(d);
  const sdDiff = sampleSd(d);
  const mae = mean(d.map(Math.abs));
  const rmse = Math.sqrt(mean(d.map((x) => x * x)));
  return {
    n: d.length,
    bias,
    sdDiff,
    loaLow: bias - 1.96 * sdDiff,
    loaHigh: bias + 1.96 * sdDiff,
    mae,
    rmse,
    proportionalBiasR: pearson(avg, d),
  };
}

export function pearson(a: readonly number[], b: readonly number[]): number {
  const ma = mean(a);
  const mb = mean(b);
  let sab = 0;
  let saa = 0;
  let sbb = 0;
  for (let i = 0; i < a.length; i++) {
    const x = (a[i] as number) - ma;
    const y = (b[i] as number) - mb;
    sab += x * y;
    saa += x * x;
    sbb += y * y;
  }
  return saa === 0 || sbb === 0 ? 0 : sab / Math.sqrt(saa * sbb);
}

/**
 * Repeatability coefficient from paired repeats: 2.77 * Sw, with
 * Sw = sqrt(sum d^2 / (2n)). 95% of repeat differences fall within +/- this value.
 */
export function repeatabilityCoefficient(first: readonly number[], second: readonly number[]): number {
  if (first.length !== second.length || first.length === 0) throw new RangeError('need equal non-empty arrays');
  let ss = 0;
  for (let i = 0; i < first.length; i++) ss += ((first[i] as number) - (second[i] as number)) ** 2;
  const sw = Math.sqrt(ss / (2 * first.length));
  return 2.77 * sw;
}

/**
 * Empirical coverage: fraction of cases where |truth - estimate| <= z * sigma.
 * A well-calibrated 95% interval (z = 1.96) should land near 0.95 on held-out data.
 */
export function coverage(
  truth: readonly number[],
  estimate: readonly number[],
  sigma: readonly number[],
  z = 1.96,
): number {
  if (truth.length !== estimate.length || truth.length !== sigma.length || truth.length === 0) {
    throw new RangeError('coverage needs three equal non-empty arrays');
  }
  let hit = 0;
  for (let i = 0; i < truth.length; i++) {
    if (Math.abs((truth[i] as number) - (estimate[i] as number)) <= z * (sigma[i] as number)) hit++;
  }
  return hit / truth.length;
}
