/**
 * Temporal aggregation of per-frame measurements into session values.
 * The reported sigma is PRECISION (frame-to-frame repeatability, correlation-corrected), never accuracy:
 * sigmaBasis is 'bootstrap' and the note says so. Accuracy needs validation against ground truth (benchmark.ts).
 */
import { type Epistemic, type Provenance, type Quantity, type ScaleStatus, insufficientEvidence, makeQuantity, weakest } from './epistemic.js';
import { effectiveN, lag1Autocorr, madOutliers, madSigma, median } from './stats.js';

interface Acc { vals: number[]; unit: Quantity['unit']; status: Epistemic[]; scaleStatus?: ScaleStatus }
export interface AggregateOptions { minN?: number; outlierK?: number; floors?: Partial<Record<Quantity['unit'], number>>; scaleRelSigma?: number }
const DEFAULT_FLOOR: Record<Quantity['unit'], number> = { px: 0.05, mm: 0.02, deg: 0.05, rad: 0.001, ratio: 0.002, rel_depth: 0.01, none: 0 };

export class MeasureAggregator {
  private acc = new Map<string, Acc>();
  private refusals = new Map<string, string>();
  add(id: string, q: Quantity): void {
    if (q.value === null) { this.refusals.set(id, q.note ?? q.refusal ?? 'unavailable'); return; }
    if (typeof q.value !== 'number' || !Number.isFinite(q.value)) return;
    const a = this.acc.get(id) ?? { vals: [], unit: q.unit, status: [] as Epistemic[] };
    if (a.unit !== q.unit) throw new Error(`unit changed for ${id}: ${a.unit} -> ${q.unit}`);
    a.vals.push(q.value); a.status.push(q.status);
    if (q.scaleStatus) a.scaleStatus = a.scaleStatus === 'METRIC_ASSUMED' || q.scaleStatus === 'METRIC_ASSUMED' ? 'METRIC_ASSUMED' : q.scaleStatus;
    this.acc.set(id, a);
  }
  count(id: string): number { return this.acc.get(id)?.vals.length ?? 0; }
  ids(): string[] { return [...new Set([...this.acc.keys(), ...this.refusals.keys()])]; }

  finalize(prov: Provenance, opt: AggregateOptions = {}): Record<string, Quantity> {
    const minN = opt.minN ?? 15, k = opt.outlierK ?? 4, out: Record<string, Quantity> = {};
    for (const id of this.ids()) {
      const a = this.acc.get(id);
      if (!a || a.vals.length < minN) { out[id] = insufficientEvidence('none', prov, `only ${a?.vals.length ?? 0} usable frames (< ${minN}); last reason: ${this.refusals.get(id) ?? 'n/a'}`); if (a) out[id] = insufficientEvidence(a.unit, prov, (out[id] as Quantity).note); continue; }
      const bad = new Set(madOutliers(a.vals, k));
      const vals = a.vals.filter((_, i) => !bad.has(i));
      const m = median(vals);
      const neff = Math.max(1, effectiveN(vals.length, lag1Autocorr(vals)));
      const floor = opt.floors?.[a.unit] ?? DEFAULT_FLOOR[a.unit];
      let sigma = Math.max(floor, (1.2533 * madSigma(vals)) / Math.sqrt(neff));
      if (a.unit === 'mm' && opt.scaleRelSigma !== undefined) sigma = Math.hypot(sigma, Math.abs(m) * opt.scaleRelSigma);
      out[id] = makeQuantity({
        value: m, unit: a.unit, status: weakest(...a.status), sigma, sigmaBasis: 'bootstrap', provenance: prov,
        ...(a.scaleStatus ? { scaleStatus: a.scaleStatus } : {}),
        note: `median of ${vals.length} frames (${bad.size} outliers rejected, effective N ${neff.toFixed(1)}); sigma = repeatability only, accuracy not validated`,
      });
    }
    return out;
  }
}
