/**
 * Learned visibility gate (see docs/neural_model.md). A logistic model per keypoint group decides whether a
 * network keypoint is actually visible, from the heatmap peak and local class probabilities. Keypoints that fail
 * are reported as hidden/unknown, never as measurements. Fitted on a synthetic calibration shard.
 */
export interface GateGroup { mean: number[]; std: number[]; w: number[]; threshold: number; n_features: number }
export interface GateModel { version: number; offsets: [number, number][]; groups: Record<string, GateGroup> }
export type GateGroupName = 'incisal_mid' | 'zenith' | 'corner' | 'papilla' | 'dental_midline';

/** Python-compatible round (half to even) so features match the training code bit-for-bit at .5 boundaries. */
export function pyRound(x: number): number {
  const f = Math.floor(x), d = x - f;
  if (d < 0.5) return f;
  if (d > 0.5) return f + 1;
  return f % 2 === 0 ? f : f + 1;
}

export function groupOf(channel: number): GateGroupName {
  if (channel < 32) return channel % 4 === 0 ? 'incisal_mid' : channel % 4 === 1 ? 'zenith' : 'corner';
  return channel < 39 ? 'papilla' : 'dental_midline';
}

/** probs: per-class probability planes (length C), each H*W row-major. */
export function gateFeatures(probs: Float32Array[], width: number, height: number, x: number, y: number, peak: number, offsets: [number, number][]): number[] {
  const f: number[] = [peak];
  for (const [dx, dy] of offsets) {
    const xi = pyRound(x + dx), yi = pyRound(y + dy);
    const x0 = Math.max(xi - 1, 0), x1 = Math.min(xi + 2, width), y0 = Math.max(yi - 1, 0), y1 = Math.min(yi + 2, height);
    for (const plane of probs) {
      if (x1 <= x0 || y1 <= y0) { f.push(0); continue; }
      let s = 0;
      for (let yy = y0; yy < y1; yy++) for (let xx = x0; xx < x1; xx++) s += plane[yy * width + xx] as number;
      f.push(s / ((x1 - x0) * (y1 - y0)));
    }
  }
  return f;
}

export function gateScore(model: GateModel, group: GateGroupName, features: number[]): { p: number; pass: boolean } {
  const g = model.groups[group];
  if (!g) throw new Error(`gate model has no group ${group}`);
  if (features.length !== g.n_features) throw new RangeError(`gate expects ${g.n_features} features, got ${features.length}`);
  let z = g.w[g.w.length - 1] as number;
  for (let i = 0; i < features.length; i++) z += (((features[i] as number) - (g.mean[i] as number)) / (g.std[i] as number)) * (g.w[i] as number);
  const p = 1 / (1 + Math.exp(-z));
  return { p, pass: p >= g.threshold };
}

export function softmaxPlanes(logits: Float32Array, classes: number, plane: number): Float32Array[] {
  const out = Array.from({ length: classes }, () => new Float32Array(plane));
  for (let i = 0; i < plane; i++) {
    let m = -Infinity;
    for (let c = 0; c < classes; c++) m = Math.max(m, logits[c * plane + i] as number);
    let s = 0;
    for (let c = 0; c < classes; c++) { const e = Math.exp((logits[c * plane + i] as number) - m); (out[c] as Float32Array)[i] = e; s += e; }
    for (let c = 0; c < classes; c++) (out[c] as Float32Array)[i] = (out[c] as Float32Array)[i]! / s;
  }
  return out;
}
