export type CameraErrorCode = 'INSECURE_CONTEXT' | 'UNSUPPORTED' | 'PERMISSION_DENIED' | 'NO_DEVICE' | 'IN_USE' | 'FAILED';
export class CameraError extends Error { constructor(public code: CameraErrorCode, message: string) { super(message); this.name = 'CameraError'; } }

export function describeCameraError(e: unknown): CameraError {
  if (e instanceof CameraError) return e;
  const name = (e as { name?: string } | null)?.name ?? '';
  if (name === 'NotAllowedError' || name === 'SecurityError') return new CameraError('PERMISSION_DENIED', 'Camera permission was denied. Allow camera access for this site in the browser settings, then retry.');
  if (name === 'NotFoundError' || name === 'OverconstrainedError') return new CameraError('NO_DEVICE', 'No suitable camera was found.');
  if (name === 'NotReadableError' || name === 'AbortError') return new CameraError('IN_USE', 'The camera is in use by another application or cannot be read.');
  return new CameraError('FAILED', `Camera failed: ${(e as Error | null)?.message ?? 'unknown error'}`);
}

export interface OpenCamera { stream: MediaStream; track: MediaStreamTrack; settings: MediaTrackSettings; label: string }

export async function openCamera(deviceId?: string): Promise<OpenCamera> {
  if (typeof window !== 'undefined' && !window.isSecureContext) throw new CameraError('INSECURE_CONTEXT', 'Camera access requires HTTPS (or localhost).');
  if (!navigator.mediaDevices?.getUserMedia) throw new CameraError('UNSUPPORTED', 'This browser does not support camera access.');
  const attempts: MediaStreamConstraints[] = [
    { video: { ...(deviceId ? { deviceId: { exact: deviceId } } : { facingMode: 'user' }), width: { ideal: 1280 }, height: { ideal: 720 }, frameRate: { ideal: 30 } }, audio: false },
    { video: deviceId ? { deviceId: { exact: deviceId } } : true, audio: false },
  ];
  let last: unknown;
  for (const c of attempts) {
    try {
      const stream = await navigator.mediaDevices.getUserMedia(c);
      const track = stream.getVideoTracks()[0];
      if (!track) throw new CameraError('NO_DEVICE', 'The camera stream has no video track.');
      return { stream, track, settings: track.getSettings(), label: track.label || 'camera' };
    } catch (e) { last = e; if ((e as { name?: string }).name === 'NotAllowedError') break; }
  }
  throw describeCameraError(last);
}
export function stopCamera(c: OpenCamera | null): void { c?.stream.getTracks().forEach((t) => t.stop()); }
export async function listCameras(): Promise<{ id: string; label: string }[]> {
  if (!navigator.mediaDevices?.enumerateDevices) return [];
  return (await navigator.mediaDevices.enumerateDevices()).filter((d) => d.kind === 'videoinput').map((d, i) => ({ id: d.deviceId, label: d.label || `Camera ${i + 1}` }));
}
