/** Frame sources: a live camera (MediaPipe) and a scripted SYNTHETIC demo. The engine only sees FrameSource. */
import { faceGeometry, innerLipPolygon, smileFromBlendshapes, MIDLINE_RIGID, EYE_OUTER, toPx, type FaceGeometry } from '@core/face';
import type { CropBox, Point, RgbaImage } from '@core/perception/pipeline';
import type { FaceTracker } from './faceTracker';

export interface SourceFrame {
  tMs: number; width: number; height: number;
  polygon: Point[]; geometry: FaceGeometry; smile: number | undefined; rigid: Point[];
  /** Interpupillary distance in source pixels from the iris landmarks (undefined if unavailable). */
  ipdPx?: number;
  /** Pixels covering `box` (clamped to the frame) and the offset of the returned image in frame coordinates. */
  grab(box: CropBox): { img: RgbaImage; ox: number; oy: number };
  /** Full frame copy (for the scale wizard). */
  snapshot(): RgbaImage;
}
export interface FrameSource {
  readonly label: string; readonly synthetic: boolean;
  next(): Promise<SourceFrame | null>;
  hint?(step: string): void;
  stop(): void;
}

export class CameraSource implements FrameSource {
  readonly synthetic = false;
  private canvas = document.createElement('canvas');
  private ctx = this.canvas.getContext('2d', { willReadFrequently: true });
  private stopped = false;
  constructor(private video: HTMLVideoElement, private tracker: FaceTracker, readonly label: string) {}

  private nextVideoFrame(): Promise<number> {
    return new Promise((resolve) => {
      const v = this.video as HTMLVideoElement & { requestVideoFrameCallback?: (cb: (now: number) => void) => number };
      if (v.requestVideoFrameCallback) v.requestVideoFrameCallback((now) => resolve(now));
      else requestAnimationFrame((now) => resolve(now));
    });
  }
  async next(): Promise<SourceFrame | null> {
    const t = await this.nextVideoFrame();
    if (this.stopped || this.video.readyState < 2 || !this.ctx) return null;
    const w = this.video.videoWidth, h = this.video.videoHeight;
    const face = this.tracker.detect(this.video, t);
    if (!face) return null;
    const lm = face.landmarks;
    const rigid = [...MIDLINE_RIGID.map((i) => toPx(lm, w, h, i)), toPx(lm, w, h, EYE_OUTER.right), toPx(lm, w, h, EYE_OUTER.left)].map((p) => ({ x: p.x, y: p.y }));
    const draw = (x: number, y: number, ww: number, hh: number): RgbaImage => {
      this.canvas.width = ww; this.canvas.height = hh;
      this.ctx!.drawImage(this.video, x, y, ww, hh, 0, 0, ww, hh);
      return this.ctx!.getImageData(0, 0, ww, hh);
    };
    const ipdPx = lm.length >= 478 ? Math.hypot((lm[473]!.x - lm[468]!.x) * w, (lm[473]!.y - lm[468]!.y) * h) : undefined;
    return {
      ...(ipdPx !== undefined ? { ipdPx } : {}),
      tMs: t, width: w, height: h, polygon: innerLipPolygon(lm, w, h), geometry: faceGeometry(lm, w, h), smile: smileFromBlendshapes(face.blendshapes), rigid,
      grab: (box) => {
        const x = Math.max(0, Math.floor(box.x0) - 2), y = Math.max(0, Math.floor(box.y0) - 2);
        const ww = Math.min(w - x, Math.ceil(box.w) + 4), hh = Math.min(h - y, Math.ceil(box.h) + 4);
        return { img: draw(x, y, ww, hh), ox: x, oy: y };
      },
      snapshot: () => draw(0, 0, w, h),
    };
  }
  stop() { this.stopped = true; }
}

export interface DemoFrameDef { file: string }
/** Scripted synthetic source: a labelled synthetic smile whose "head pose" follows the capture step. Never a patient. */
export class DemoSource implements FrameSource {
  readonly synthetic = true; readonly label = 'SYNTHETIC DEMO (generated images, not a patient)';
  private step = 'CENTER'; private stopped = false; private n = 0;
  constructor(private images: RgbaImage[], private frameMs = 33) {}
  hint(step: string) { this.step = step; }
  async next(): Promise<SourceFrame | null> {
    await new Promise((r) => setTimeout(r, this.frameMs));
    if (this.stopped) return null;
    const img = this.images[Math.floor(this.n++ / 400) % this.images.length] as RgbaImage;
    const w = img.width, h = img.height, yaw = this.step === 'LEFT' ? 15 : this.step === 'RIGHT' ? -15 : 0, roll = this.step === 'TILT' ? 6 : 0;
    const geometry: FaceGeometry = { midlineXAt: () => w / 2, eyeLineDeg: roll, pose: { yawDeg: yaw, pitchDeg: 0, rollDeg: roll }, mouthWidthPx: 0.86 * w, interocularPx: 2.2 * w };
    const polygon: Point[] = [{ x: w / 2 - 0.43 * w, y: h * 0.4 }, { x: w / 2 + 0.43 * w, y: h * 0.4 }, { x: w / 2 + 0.43 * w, y: h * 0.6 }, { x: w / 2 - 0.43 * w, y: h * 0.6 }];
    const rigid = [{ x: w * 0.3, y: h * 0.1 }, { x: w * 0.7, y: h * 0.1 }];
    return { tMs: this.n * this.frameMs, width: w, height: h, polygon, geometry, smile: this.step === 'SMILE' ? 0.9 : 0.2, rigid, grab: () => ({ img, ox: 0, oy: 0 }), snapshot: () => img };
  }
  stop() { this.stopped = true; }
}
