/** Small dense linear algebra for calibration and bundle adjustment (n <= ~200). */
import { solveLinear, invert } from './pose.js';
export { solveLinear, invert };

/** Symmetric eigen-decomposition by cyclic Jacobi rotations. Eigenvalues ascending; vectors[i] is the eigenvector for values[i]. */
export function jacobiEigen(Ain: number[][], maxSweeps = 60): { values: number[]; vectors: number[][] } {
  const n = Ain.length, A = Ain.map((r) => r.slice());
  const V: number[][] = Array.from({ length: n }, (_, i) => Array.from({ length: n }, (_, j) => (i === j ? 1 : 0)));
  for (let sweep = 0; sweep < maxSweeps; sweep++) {
    let off = 0;
    for (let i = 0; i < n; i++) for (let j = i + 1; j < n; j++) off += (A[i]![j] as number) ** 2;
    if (off < 1e-24) break;
    for (let p = 0; p < n; p++) for (let q = p + 1; q < n; q++) {
      const apq = A[p]![q] as number; if (Math.abs(apq) < 1e-300) continue;
      const th = ((A[q]![q] as number) - (A[p]![p] as number)) / (2 * apq);
      const t = Math.sign(th || 1) / (Math.abs(th) + Math.sqrt(th * th + 1)), c = 1 / Math.sqrt(t * t + 1), s = t * c;
      for (let k = 0; k < n; k++) { const akp = A[k]![p] as number, akq = A[k]![q] as number; A[k]![p] = c * akp - s * akq; A[k]![q] = s * akp + c * akq; }
      for (let k = 0; k < n; k++) { const apk = A[p]![k] as number, aqk = A[q]![k] as number; A[p]![k] = c * apk - s * aqk; A[q]![k] = s * apk + c * aqk; }
      for (let k = 0; k < n; k++) { const vkp = V[k]![p] as number, vkq = V[k]![q] as number; V[k]![p] = c * vkp - s * vkq; V[k]![q] = s * vkp + c * vkq; }
    }
  }
  const order = [...Array(n).keys()].sort((a, b) => (A[a]![a] as number) - (A[b]![b] as number));
  return { values: order.map((i) => A[i]![i] as number), vectors: order.map((i) => V.map((row) => row[i] as number)) };
}

export const matMul = (A: number[][], B: number[][]): number[][] => A.map((r) => B[0]!.map((_, j) => r.reduce((s, v, k) => s + v * (B[k]![j] as number), 0)));
export const transpose = (A: number[][]): number[][] => A[0]!.map((_, j) => A.map((r) => r[j] as number));
export const AtA = (A: number[][]): number[][] => matMul(transpose(A), A);
